contracts/AccessControl.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title AccessControl
 * @dev Gas-efficient token-based access control
 * @notice Checks token balance for access, supports time-based holding requirements
 */
contract AccessControl is Ownable {
    // Token address for access control
    IERC20 public accessToken;
    
    // Minimum balance required for access
    uint256 public minBalance;
    
    // Minimum holding time (in seconds, 0 = no time requirement)
    uint256 public minHoldingTime;
    
    // Track when users first acquired tokens
    mapping(address => uint256) public tokenAcquiredAt;
    
    // Cached access status (to reduce repeated checks)
    mapping(address => uint256) public cachedAccessUntil; // Timestamp until which access is cached
    
    // Cache duration (default 1 hour)
    uint256 public cacheDuration = 3600;
    
    // Events
    event AccessTokenUpdated(address indexed oldToken, address indexed newToken);
    event MinBalanceUpdated(uint256 oldBalance, uint256 newBalance);
    event MinHoldingTimeUpdated(uint256 oldTime, uint256 newTime);
    event AccessGranted(address indexed user);
    event AccessDenied(address indexed user, string reason);
    
    /**
     * @dev Constructor
     * @param _accessToken Address of the token used for access control
     * @param _minBalance Minimum token balance required
     * @param _minHoldingTime Minimum holding time in seconds (0 = no requirement)
     */
    constructor(
        address _accessToken,
        uint256 _minBalance,
        uint256 _minHoldingTime
    ) Ownable(msg.sender) {
        require(_accessToken != address(0), "AccessControl: Invalid token address");
        accessToken = IERC20(_accessToken);
        minBalance = _minBalance;
        minHoldingTime = _minHoldingTime;
    }
    
    /**
     * @dev Check if user has access (with caching)
     * @param user User address to check
     * @return hasAccess Whether user has access
     */
    function hasAccess(address user) external view returns (bool) {
        // Check cache first
        if (block.timestamp < cachedAccessUntil[user]) {
            return true;
        }
        
        return _checkAccess(user);
    }
    
    /**
     * @dev Internal function to check access (without cache)
     * @param user User address to check
     * @return hasAccess Whether user has access
     */
    function _checkAccess(address user) internal view returns (bool) {
        // Check balance
        uint256 balance = accessToken.balanceOf(user);
        if (balance < minBalance) {
            return false;
        }
        
        // Check holding time if required
        if (minHoldingTime > 0) {
            uint256 acquiredAt = tokenAcquiredAt[user];
            if (acquiredAt == 0) {
                // User hasn't been tracked yet, assume they just acquired
                return false;
            }
            if (block.timestamp < acquiredAt + minHoldingTime) {
                return false;
            }
        }
        
        return true;
    }
    
    /**
     * @dev Check access and update cache if granted
     * @param user User address to check
     * @return hasAccess Whether user has access
     */
    function checkAndCacheAccess(address user) external returns (bool) {
        bool hasAccess_ = _checkAccess(user);
        
        if (hasAccess_) {
            // Cache access for cacheDuration
            cachedAccessUntil[user] = block.timestamp + cacheDuration;
            emit AccessGranted(user);
        } else {
            emit AccessDenied(user, "Insufficient balance or holding time");
        }
        
        return hasAccess_;
    }
    
    /**
     * @dev Record when user acquired tokens (called by token contract or external)
     * @param user User address
     */
    function recordTokenAcquisition(address user) external {
        if (tokenAcquiredAt[user] == 0) {
            tokenAcquiredAt[user] = block.timestamp;
        }
    }
    
    /**
     * @dev Update access token (only owner)
     * @param _accessToken New token address
     */
    function setAccessToken(address _accessToken) external onlyOwner {
        require(_accessToken != address(0), "AccessControl: Invalid token address");
        address oldToken = address(accessToken);
        accessToken = IERC20(_accessToken);
        emit AccessTokenUpdated(oldToken, _accessToken);
    }
    
    /**
     * @dev Update minimum balance (only owner)
     * @param _minBalance New minimum balance
     */
    function setMinBalance(uint256 _minBalance) external onlyOwner {
        uint256 oldBalance = minBalance;
        minBalance = _minBalance;
        emit MinBalanceUpdated(oldBalance, _minBalance);
    }
    
    /**
     * @dev Update minimum holding time (only owner)
     * @param _minHoldingTime New minimum holding time in seconds
     */
    function setMinHoldingTime(uint256 _minHoldingTime) external onlyOwner {
        uint256 oldTime = minHoldingTime;
        minHoldingTime = _minHoldingTime;
        emit MinHoldingTimeUpdated(oldTime, _minHoldingTime);
    }
    
    /**
     * @dev Update cache duration (only owner)
     * @param _cacheDuration New cache duration in seconds
     */
    function setCacheDuration(uint256 _cacheDuration) external onlyOwner {
        cacheDuration = _cacheDuration;
    }
    
    /**
     * @dev Clear cache for a user (only owner)
     * @param user User address
     */
    function clearCache(address user) external onlyOwner {
        cachedAccessUntil[user] = 0;
    }
}

contracts/AdminDashboard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./DAppRegistry.sol";
import "./FeeHandler.sol";
import "./Treasury.sol";

/**
 * @title AdminDashboard
 * @dev Admin-only dApp for platform management
 * @notice Multi-sig support for critical operations
 */
contract AdminDashboard is AccessControl, ReentrancyGuard {
    // Admin role
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    
    // Contracts
    DAppRegistry public dAppRegistry;
    FeeHandler public feeHandler;
    Treasury public treasury;
    
    // Multi-sig threshold (number of admins required)
    uint256 public multiSigThreshold = 2;
    
    // Pending operations
    struct PendingOperation {
        bytes32 operationHash;
        address proposer;
        uint256 approvals;
        mapping(address => bool) approvers;
        bool executed;
    }
    
    mapping(bytes32 => PendingOperation) public pendingOperations;
    bytes32[] public pendingOperationIds;
    
    // Events
    event OperationProposed(bytes32 indexed operationId, bytes32 operationHash, address indexed proposer);
    event OperationApproved(bytes32 indexed operationId, address indexed approver);
    event OperationExecuted(bytes32 indexed operationId);
    event MultiSigThresholdUpdated(uint256 oldThreshold, uint256 newThreshold);
    
    /**
     * @dev Constructor
     * @param _dAppRegistry DAppRegistry contract address
     * @param _feeHandler FeeHandler contract address
     * @param _treasury Treasury contract address
     */
    constructor(
        address _dAppRegistry,
        address _feeHandler,
        address _treasury
    ) {
        require(_dAppRegistry != address(0), "AdminDashboard: Invalid DAppRegistry");
        require(_feeHandler != address(0), "AdminDashboard: Invalid FeeHandler");
        require(_treasury != address(0), "AdminDashboard: Invalid Treasury");
        
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        
        dAppRegistry = DAppRegistry(_dAppRegistry);
        feeHandler = FeeHandler(_feeHandler);
        treasury = Treasury(_treasury);
    }
    
    /**
     * @dev Propose an operation (requires multi-sig)
     * @param operationHash Hash of the operation to execute
     * @return operationId Operation ID
     */
    function proposeOperation(bytes32 operationHash) external onlyRole(ADMIN_ROLE) returns (bytes32) {
        bytes32 operationId = keccak256(abi.encodePacked(operationHash, block.timestamp, msg.sender));
        
        PendingOperation storage op = pendingOperations[operationId];
        op.operationHash = operationHash;
        op.proposer = msg.sender;
        op.approvals = 1;
        op.approvers[msg.sender] = true;
        op.executed = false;
        
        pendingOperationIds.push(operationId);
        
        emit OperationProposed(operationId, operationHash, msg.sender);
        
        return operationId;
    }
    
    /**
     * @dev Approve an operation
     * @param operationId Operation ID
     */
    function approveOperation(bytes32 operationId) external onlyRole(ADMIN_ROLE) {
        PendingOperation storage op = pendingOperations[operationId];
        require(op.operationHash != bytes32(0), "AdminDashboard: Operation not found");
        require(!op.executed, "AdminDashboard: Operation already executed");
        require(!op.approvers[msg.sender], "AdminDashboard: Already approved");
        
        op.approvals++;
        op.approvers[msg.sender] = true;
        
        emit OperationApproved(operationId, msg.sender);
        
        // Auto-execute if threshold reached
        if (op.approvals >= multiSigThreshold) {
            _executeOperation(operationId);
        }
    }
    
    /**
     * @dev Execute an operation (internal)
     * @param operationId Operation ID
     */
    function _executeOperation(bytes32 operationId) internal {
        PendingOperation storage op = pendingOperations[operationId];
        require(op.approvals >= multiSigThreshold, "AdminDashboard: Insufficient approvals");
        require(!op.executed, "AdminDashboard: Already executed");
        
        op.executed = true;
        emit OperationExecuted(operationId);
    }
    
    /**
     * @dev Approve a dApp (single admin, no multi-sig)
     * @param dAppId dApp ID
     */
    function approveDApp(uint256 dAppId) external onlyRole(ADMIN_ROLE) {
        dAppRegistry.updateDAppStatus(dAppId, true);
    }
    
    /**
     * @dev Set fee rates (requires multi-sig)
     * @param newKasparexPercentage New Kasparex percentage (basis points)
     * @param newProjectPercentage New project percentage (basis points)
     */
    function setFeeRates(uint256 newKasparexPercentage, uint256 newProjectPercentage) external onlyRole(ADMIN_ROLE) {
        // This would require updating FeeHandler contract
        // For now, just emit event
        require(newKasparexPercentage + newProjectPercentage == 10000, "AdminDashboard: Percentages must sum to 100%");
    }
    
    /**
     * @dev Update multi-sig threshold (requires multi-sig)
     * @param newThreshold New threshold
     */
    function setMultiSigThreshold(uint256 newThreshold) external onlyRole(ADMIN_ROLE) {
        require(newThreshold > 0, "AdminDashboard: Invalid threshold");
        uint256 oldThreshold = multiSigThreshold;
        multiSigThreshold = newThreshold;
        emit MultiSigThresholdUpdated(oldThreshold, newThreshold);
    }
    
    /**
     * @dev Get pending operations
     * @return Array of operation IDs
     */
    function getPendingOperations() external view returns (bytes32[] memory) {
        return pendingOperationIds;
    }
    
    /**
     * @dev Get operation details
     * @param operationId Operation ID
     * @return operationHash Operation hash
     * @return proposer Proposer address
     * @return approvals Number of approvals
     * @return executed Whether executed
     */
    function getOperation(bytes32 operationId) external view returns (
        bytes32 operationHash,
        address proposer,
        uint256 approvals,
        bool executed
    ) {
        PendingOperation storage op = pendingOperations[operationId];
        return (op.operationHash, op.proposer, op.approvals, op.executed);
    }
}

contracts/AffiliateManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title AffiliateManager
 * @dev Tracks referrals and distributes rewards
 * @notice Handles referral tracking via ?ref= parameter in widget embeds
 */
contract AffiliateManager is Ownable, ReentrancyGuard {
    // Referral structure
    struct Referral {
        address affiliate;
        address user;
        address dAppContract;
        uint256 timestamp;
        bool rewarded;
    }
    
    // Track referrals
    mapping(address => Referral[]) public userReferrals; // user -> referrals
    mapping(address => Referral[]) public affiliateReferrals; // affiliate -> referrals
    mapping(address => mapping(address => uint256)) public referralCounts; // affiliate -> dApp -> count
    
    // Referral rewards (basis points, e.g., 500 = 5%)
    uint256 public referralRewardRate = 500; // 5% default
    
    // Rate limiting (max referrals per affiliate per dApp per day)
    uint256 public maxReferralsPerDay = 100;
    mapping(address => mapping(address => mapping(uint256 => uint256))) public dailyReferralCounts; // affiliate -> dApp -> day -> count
    
    // Reward token (GRID or dApp token)
    IERC20 public rewardToken;
    
    // Events
    event ReferralRecorded(
        address indexed affiliate,
        address indexed user,
        address indexed dAppContract,
        uint256 timestamp
    );
    event ReferralRewarded(
        address indexed affiliate,
        address indexed dAppContract,
        uint256 amount,
        uint256 timestamp
    );
    event ReferralRateUpdated(uint256 oldRate, uint256 newRate);
    event RewardTokenUpdated(address indexed oldToken, address indexed newToken);
    
    /**
     * @dev Constructor
     * @param _rewardToken Address of reward token (GRID or dApp token)
     */
    constructor(address _rewardToken) Ownable(msg.sender) {
        require(_rewardToken != address(0), "AffiliateManager: Invalid reward token");
        rewardToken = IERC20(_rewardToken);
    }
    
    /**
     * @dev Record a referral
     * @param affiliate Affiliate address (from ?ref= parameter)
     * @param user User address
     * @param dAppContract dApp contract address
     */
    function recordReferral(
        address affiliate,
        address user,
        address dAppContract
    ) external nonReentrant {
        require(affiliate != address(0), "AffiliateManager: Invalid affiliate");
        require(user != address(0), "AffiliateManager: Invalid user");
        require(dAppContract != address(0), "AffiliateManager: Invalid dApp contract");
        require(affiliate != user, "AffiliateManager: Cannot refer yourself");
        
        // Check rate limiting
        uint256 day = block.timestamp / 86400; // Days since epoch
        dailyReferralCounts[affiliate][dAppContract][day]++;
        require(
            dailyReferralCounts[affiliate][dAppContract][day] <= maxReferralsPerDay,
            "AffiliateManager: Rate limit exceeded"
        );
        
        Referral memory referral = Referral({
            affiliate: affiliate,
            user: user,
            dAppContract: dAppContract,
            timestamp: block.timestamp,
            rewarded: false
        });
        
        userReferrals[user].push(referral);
        affiliateReferrals[affiliate].push(referral);
        referralCounts[affiliate][dAppContract]++;
        
        emit ReferralRecorded(affiliate, user, dAppContract, block.timestamp);
    }
    
    /**
     * @dev Distribute referral reward
     * @param affiliate Affiliate address
     * @param dAppContract dApp contract address
     * @param actionValue Value of the action (for calculating reward)
     */
    function distributeReferralReward(
        address affiliate,
        address dAppContract,
        uint256 actionValue
    ) external nonReentrant {
        require(affiliate != address(0), "AffiliateManager: Invalid affiliate");
        require(dAppContract != address(0), "AffiliateManager: Invalid dApp contract");
        
        uint256 rewardAmount = (actionValue * referralRewardRate) / 10000;
        if (rewardAmount == 0) {
            return;
        }
        
        require(
            rewardToken.balanceOf(address(this)) >= rewardAmount,
            "AffiliateManager: Insufficient reward balance"
        );
        
        require(
            rewardToken.transfer(affiliate, rewardAmount),
            "AffiliateManager: Reward transfer failed"
        );
        
        emit ReferralRewarded(affiliate, dAppContract, rewardAmount, block.timestamp);
    }
    
    /**
     * @dev Get referral count for an affiliate
     * @param affiliate Affiliate address
     * @param dAppContract dApp contract address
     * @return Referral count
     */
    function getReferralCount(address affiliate, address dAppContract) external view returns (uint256) {
        return referralCounts[affiliate][dAppContract];
    }
    
    /**
     * @dev Get user's referrals
     * @param user User address
     * @return Array of referrals
     */
    function getUserReferrals(address user) external view returns (Referral[] memory) {
        return userReferrals[user];
    }
    
    /**
     * @dev Get affiliate's referrals
     * @param affiliate Affiliate address
     * @return Array of referrals
     */
    function getAffiliateReferrals(address affiliate) external view returns (Referral[] memory) {
        return affiliateReferrals[affiliate];
    }
    
    /**
     * @dev Update referral reward rate (only owner)
     * @param _rate New reward rate in basis points
     */
    function setReferralRewardRate(uint256 _rate) external onlyOwner {
        require(_rate <= 10000, "AffiliateManager: Rate cannot exceed 100%");
        uint256 oldRate = referralRewardRate;
        referralRewardRate = _rate;
        emit ReferralRateUpdated(oldRate, _rate);
    }
    
    /**
     * @dev Update reward token (only owner)
     * @param _rewardToken New reward token address
     */
    function setRewardToken(address _rewardToken) external onlyOwner {
        require(_rewardToken != address(0), "AffiliateManager: Invalid reward token");
        address oldToken = address(rewardToken);
        rewardToken = IERC20(_rewardToken);
        emit RewardTokenUpdated(oldToken, _rewardToken);
    }
    
    /**
     * @dev Update max referrals per day (only owner)
     * @param _maxReferrals New maximum referrals per day
     */
    function setMaxReferralsPerDay(uint256 _maxReferrals) external onlyOwner {
        maxReferralsPerDay = _maxReferrals;
    }
}

contracts/AuthorizationRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title AuthorizationRegistry
 * @dev Registry for managing developer assignments to dApps
 * @notice Admins can assign wallet addresses as Developers for specific dApps
 */
contract AuthorizationRegistry is AccessControl {
    // Role for developers (extensible for future roles)
    bytes32 public constant DEVELOPER_ROLE = keccak256("DEVELOPER_ROLE");

    // Mapping: dAppId => wallet => hasDeveloperRole
    mapping(uint256 => mapping(address => bool)) public dAppDevelopers;

    // Mapping: dAppId => array of developer addresses
    mapping(uint256 => address[]) public dAppDeveloperList;

    // Mapping: wallet => array of dAppIds where wallet is developer
    mapping(address => uint256[]) public developerDApps;

    // Events
    event DeveloperAssigned(
        uint256 indexed dAppId,
        address indexed developer,
        address indexed assignedBy,
        uint256 timestamp
    );
    event DeveloperRevoked(
        uint256 indexed dAppId,
        address indexed developer,
        address indexed revokedBy,
        uint256 timestamp
    );

    /**
     * @dev Constructor sets up default admin role
     */
    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    /**
     * @dev Internal function to assign a developer role to a wallet for a specific dApp
     * @param _dAppId ID of the dApp
     * @param _developer Address of the developer to assign
     */
    function _assignDeveloper(
        uint256 _dAppId,
        address _developer
    ) internal {
        require(_dAppId > 0, "AuthorizationRegistry: Invalid dApp ID");
        require(_developer != address(0), "AuthorizationRegistry: Invalid developer address");
        require(
            !dAppDevelopers[_dAppId][_developer],
            "AuthorizationRegistry: Developer already assigned"
        );

        // Add to mapping
        dAppDevelopers[_dAppId][_developer] = true;

        // Add to dApp's developer list if not already present
        bool exists = false;
        for (uint256 i = 0; i < dAppDeveloperList[_dAppId].length; i++) {
            if (dAppDeveloperList[_dAppId][i] == _developer) {
                exists = true;
                break;
            }
        }
        if (!exists) {
            dAppDeveloperList[_dAppId].push(_developer);
        }

        // Add to developer's dApp list if not already present
        exists = false;
        for (uint256 i = 0; i < developerDApps[_developer].length; i++) {
            if (developerDApps[_developer][i] == _dAppId) {
                exists = true;
                break;
            }
        }
        if (!exists) {
            developerDApps[_developer].push(_dAppId);
        }

        emit DeveloperAssigned(_dAppId, _developer, msg.sender, block.timestamp);
    }

    /**
     * @dev Assign a developer role to a wallet for a specific dApp
     * @param _dAppId ID of the dApp
     * @param _developer Address of the developer to assign
     */
    function assignDeveloper(
        uint256 _dAppId,
        address _developer
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _assignDeveloper(_dAppId, _developer);
    }

    /**
     * @dev Internal function to revoke developer role from a wallet for a specific dApp
     * @param _dAppId ID of the dApp
     * @param _developer Address of the developer to revoke
     */
    function _revokeDeveloper(
        uint256 _dAppId,
        address _developer
    ) internal {
        require(_dAppId > 0, "AuthorizationRegistry: Invalid dApp ID");
        require(_developer != address(0), "AuthorizationRegistry: Invalid developer address");
        require(
            dAppDevelopers[_dAppId][_developer],
            "AuthorizationRegistry: Developer not assigned"
        );

        // Remove from mapping
        dAppDevelopers[_dAppId][_developer] = false;

        // Remove from dApp's developer list
        address[] storage devList = dAppDeveloperList[_dAppId];
        for (uint256 i = 0; i < devList.length; i++) {
            if (devList[i] == _developer) {
                devList[i] = devList[devList.length - 1];
                devList.pop();
                break;
            }
        }

        // Remove from developer's dApp list
        uint256[] storage dAppList = developerDApps[_developer];
        for (uint256 i = 0; i < dAppList.length; i++) {
            if (dAppList[i] == _dAppId) {
                dAppList[i] = dAppList[dAppList.length - 1];
                dAppList.pop();
                break;
            }
        }

        emit DeveloperRevoked(_dAppId, _developer, msg.sender, block.timestamp);
    }

    /**
     * @dev Revoke developer role from a wallet for a specific dApp
     * @param _dAppId ID of the dApp
     * @param _developer Address of the developer to revoke
     */
    function revokeDeveloper(
        uint256 _dAppId,
        address _developer
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeDeveloper(_dAppId, _developer);
    }

    /**
     * @dev Check if a wallet has developer role for a specific dApp
     * @param _dAppId ID of the dApp
     * @param _developer Address of the developer to check
     * @return bool True if developer is assigned
     */
    function isDeveloper(
        uint256 _dAppId,
        address _developer
    ) external view returns (bool) {
        return dAppDevelopers[_dAppId][_developer];
    }

    /**
     * @dev Get all developers for a specific dApp
     * @param _dAppId ID of the dApp
     * @return address[] Array of developer addresses
     */
    function getDAppDevelopers(
        uint256 _dAppId
    ) external view returns (address[] memory) {
        return dAppDeveloperList[_dAppId];
    }

    /**
     * @dev Get all dApp IDs where a wallet is assigned as developer
     * @param _developer Address of the developer
     * @return uint256[] Array of dApp IDs
     */
    function getDeveloperDApps(
        address _developer
    ) external view returns (uint256[] memory) {
        return developerDApps[_developer];
    }

    /**
     * @dev Batch assign developers to a dApp
     * @param _dAppId ID of the dApp
     * @param _developers Array of developer addresses to assign
     */
    function batchAssignDevelopers(
        uint256 _dAppId,
        address[] calldata _developers
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_dAppId > 0, "AuthorizationRegistry: Invalid dApp ID");
        for (uint256 i = 0; i < _developers.length; i++) {
            if (_developers[i] != address(0) && !dAppDevelopers[_dAppId][_developers[i]]) {
                _assignDeveloper(_dAppId, _developers[i]);
            }
        }
    }

    /**
     * @dev Batch revoke developers from a dApp
     * @param _dAppId ID of the dApp
     * @param _developers Array of developer addresses to revoke
     */
    function batchRevokeDevelopers(
        uint256 _dAppId,
        address[] calldata _developers
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_dAppId > 0, "AuthorizationRegistry: Invalid dApp ID");
        for (uint256 i = 0; i < _developers.length; i++) {
            if (_developers[i] != address(0) && dAppDevelopers[_dAppId][_developers[i]]) {
                _revokeDeveloper(_dAppId, _developers[i]);
            }
        }
    }
}

contracts/CommentCredits.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title CommentCredits
 * @dev Smart contract for managing comment credits and storing comments on-chain
 * @notice Users purchase credits with KAS, then use credits to submit comments
 */
contract CommentCredits is Ownable, ReentrancyGuard {
    // Credit structure
    struct CreditBalance {
        uint256 creditsRemaining;
        uint256 totalPurchased;
        bool hasUnlimitedCredits; // For 100M+ KREX holders
        uint256 lastPurchaseDate;
    }

    // Comment structure
    struct Comment {
        uint256 id;
        string articleId; // Can be article ID or dApp ID/slug
        address author;
        string content;
        uint256 timestamp;
        uint256 parentCommentId; // 0 if top-level comment
        bool deleted;
    }

    // Credit balances per user
    mapping(address => CreditBalance) public creditBalances;
    
    // Comments storage
    mapping(uint256 => Comment) public comments;
    mapping(string => uint256[]) public commentsByArticle; // articleId => comment IDs
    
    // Comment counter
    uint256 public commentCounter;
    
    // Pricing
    uint256 public constant BASE_CREDITS_PER_KAS = 1; // 1 credit per KAS (base rate)
    uint256 public constant KREX_UNLIMITED_THRESHOLD = 100_000_000 * 1e8; // 100M KREX (assuming 8 decimals)
    
    // KREX token address (to check balance for unlimited credits)
    address public krexTokenAddress;
    
    // Events
    event CreditsPurchased(
        address indexed user,
        uint256 credits,
        uint256 kasAmount,
        uint256 timestamp
    );
    
    event CreditUsed(
        address indexed user,
        uint256 creditsRemaining,
        uint256 timestamp
    );
    
    event CommentSubmitted(
        uint256 indexed commentId,
        string indexed articleId,
        address indexed author,
        string content,
        uint256 timestamp,
        uint256 parentCommentId
    );
    
    event CommentDeleted(
        uint256 indexed commentId,
        address indexed author,
        uint256 timestamp
    );
    
    event UnlimitedCreditsGranted(
        address indexed user,
        uint256 timestamp
    );
    
    event KREXTokenAddressUpdated(address indexed oldAddress, address indexed newAddress);

    /**
     * @dev Constructor
     * @param _krexTokenAddress Address of KREX token contract (for unlimited credits check)
     */
    constructor(address _krexTokenAddress) Ownable(msg.sender) {
        krexTokenAddress = _krexTokenAddress;
        commentCounter = 0;
    }

    /**
     * @dev Purchase comment credits
     * @notice Users send KAS to purchase credits (1 KAS = 1 credit base rate)
     */
    function purchaseCredits() public payable nonReentrant {
        require(msg.value > 0, "CommentCredits: Must send KAS to purchase credits");
        
        uint256 creditsToAdd = msg.value / 1e8; // Convert KAS (assuming 8 decimals) to credits
        require(creditsToAdd > 0, "CommentCredits: Amount too small");
        
        CreditBalance storage balance = creditBalances[msg.sender];
        balance.creditsRemaining += creditsToAdd;
        balance.totalPurchased += creditsToAdd;
        balance.lastPurchaseDate = block.timestamp;
        
        emit CreditsPurchased(msg.sender, creditsToAdd, msg.value, block.timestamp);
    }

    /**
     * @dev Submit a comment (requires credits)
     * @param _articleId Article ID or dApp ID/slug
     * @param _content Comment content (stored fully on-chain)
     * @param _parentCommentId Parent comment ID (0 for top-level comments)
     * @return commentId The ID of the created comment
     */
    function submitComment(
        string memory _articleId,
        string memory _content,
        uint256 _parentCommentId
    ) external nonReentrant returns (uint256) {
        require(bytes(_content).length > 0, "CommentCredits: Comment cannot be empty");
        require(bytes(_articleId).length > 0, "CommentCredits: Article ID cannot be empty");
        
        CreditBalance storage balance = creditBalances[msg.sender];
        
        // Check if user has unlimited credits (100M+ KREX)
        if (!balance.hasUnlimitedCredits) {
            // Check KREX balance if token address is set
            if (krexTokenAddress != address(0)) {
                // TODO: Implement KREX balance check via ERC20 interface
                // For now, unlimited credits must be set manually by owner
            }
            
            // Check if user has credits
            require(balance.creditsRemaining > 0, "CommentCredits: Insufficient credits");
            
            // Deduct credit
            balance.creditsRemaining -= 1;
            emit CreditUsed(msg.sender, balance.creditsRemaining, block.timestamp);
        }
        
        // Create comment
        commentCounter++;
        Comment memory newComment = Comment({
            id: commentCounter,
            articleId: _articleId,
            author: msg.sender,
            content: _content,
            timestamp: block.timestamp,
            parentCommentId: _parentCommentId,
            deleted: false
        });
        
        comments[commentCounter] = newComment;
        commentsByArticle[_articleId].push(commentCounter);
        
        emit CommentSubmitted(
            commentCounter,
            _articleId,
            msg.sender,
            _content,
            block.timestamp,
            _parentCommentId
        );
        
        return commentCounter;
    }

    /**
     * @dev Delete a comment (does NOT remove from chain, does NOT refund credits)
     * @param _commentId ID of the comment to delete
     */
    function deleteComment(uint256 _commentId) external nonReentrant {
        Comment storage comment = comments[_commentId];
        require(comment.id > 0, "CommentCredits: Comment does not exist");
        require(comment.author == msg.sender, "CommentCredits: Not authorized");
        require(!comment.deleted, "CommentCredits: Comment already deleted");
        
        comment.deleted = true;
        
        emit CommentDeleted(_commentId, msg.sender, block.timestamp);
    }

    /**
     * @dev Get comment by ID
     * @param _commentId Comment ID
     * @return Comment struct
     */
    function getComment(uint256 _commentId) external view returns (Comment memory) {
        return comments[_commentId];
    }

    /**
     * @dev Get all comment IDs for an article
     * @param _articleId Article ID or dApp ID/slug
     * @return Array of comment IDs
     */
    function getCommentIdsByArticle(string memory _articleId) external view returns (uint256[] memory) {
        return commentsByArticle[_articleId];
    }

    /**
     * @dev Get multiple comments by IDs
     * @param _commentIds Array of comment IDs
     * @return Array of Comment structs
     */
    function getComments(uint256[] memory _commentIds) external view returns (Comment[] memory) {
        Comment[] memory result = new Comment[](_commentIds.length);
        for (uint256 i = 0; i < _commentIds.length; i++) {
            result[i] = comments[_commentIds[i]];
        }
        return result;
    }

    /**
     * @dev Get credit balance for a user
     * @param _user User address
     * @return CreditBalance struct
     */
    function getCreditBalance(address _user) external view returns (CreditBalance memory) {
        return creditBalances[_user];
    }

    /**
     * @dev Grant unlimited credits to a user (for 100M+ KREX holders)
     * @param _user User address
     */
    function grantUnlimitedCredits(address _user) external onlyOwner {
        require(_user != address(0), "CommentCredits: Invalid user");
        creditBalances[_user].hasUnlimitedCredits = true;
        emit UnlimitedCreditsGranted(_user, block.timestamp);
    }

    /**
     * @dev Revoke unlimited credits from a user
     * @param _user User address
     */
    function revokeUnlimitedCredits(address _user) external onlyOwner {
        require(_user != address(0), "CommentCredits: Invalid user");
        creditBalances[_user].hasUnlimitedCredits = false;
    }

    /**
     * @dev Update KREX token address
     * @param _newAddress New KREX token address
     */
    function setKREXTokenAddress(address _newAddress) external onlyOwner {
        address oldAddress = krexTokenAddress;
        krexTokenAddress = _newAddress;
        emit KREXTokenAddressUpdated(oldAddress, _newAddress);
    }

    /**
     * @dev Withdraw collected KAS (for contract owner)
     */
    function withdraw() external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "CommentCredits: No funds to withdraw");
        payable(owner()).transfer(balance);
    }

    /**
     * @dev Receive function to accept KAS payments
     */
    receive() external payable {
        // Allow direct KAS transfers for credit purchases
        if (msg.value > 0) {
            purchaseCredits();
        }
    }
}

contracts/DAOVoting.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./FeeCollector.sol";

/**
 * @title DAOVoting
 * @dev DAO Voting contract for submitting and voting on dApp proposals
 * @notice Allows users to submit proposals with a fee and vote on them
 */
contract DAOVoting is Ownable, ReentrancyGuard {
    // Fee collector contract
    FeeCollector public feeCollector;

    // Vote struct to track user votes
    struct Vote {
        bool support; // true = yes, false = no
        uint256 timestamp;
    }

    // Proposal struct
    struct Proposal {
        uint256 id;
        string title;
        string description;
        address proposer;
        uint256 submissionFee;
        uint256 voteFee;
        uint256 yesVotes;
        uint256 noVotes;
        uint256 createdAt;
        bool isFlagged;
        bool isActive;
    }

    // State variables
    mapping(uint256 => Proposal) public proposals;
    mapping(uint256 => mapping(address => Vote)) public votes; // proposalId => voter => vote
    uint256 public proposalCount;
    uint256 public submissionFee; // Fee to submit proposal (10 KAS)
    uint256 public voteFee; // Fee per vote (1 KAS)
    uint256 public flagThreshold; // Vote threshold to auto-flag (e.g., 50 votes)

    // Events
    event ProposalSubmitted(
        uint256 indexed proposalId,
        address indexed proposer,
        string title,
        uint256 timestamp
    );
    event VoteCast(
        uint256 indexed proposalId,
        address indexed voter,
        bool support,
        uint256 timestamp
    );
    event VoteChanged(
        uint256 indexed proposalId,
        address indexed voter,
        bool oldSupport,
        bool newSupport,
        uint256 timestamp
    );
    event ProposalFlagged(
        uint256 indexed proposalId,
        uint256 yesVotes,
        uint256 noVotes,
        uint256 timestamp
    );
    event SubmissionFeeUpdated(uint256 oldFee, uint256 newFee);
    event VoteFeeUpdated(uint256 oldFee, uint256 newFee);
    event FlagThresholdUpdated(uint256 oldThreshold, uint256 newThreshold);
    event FeeCollectorUpdated(address indexed oldCollector, address indexed newCollector);

    /**
     * @dev Constructor sets fee collector and initial fees
     * @param _feeCollector Address of the FeeCollector contract
     * @param _submissionFee Initial submission fee (10 KAS = 10 * 10^18)
     * @param _voteFee Initial vote fee (1 KAS = 1 * 10^18)
     * @param _flagThreshold Initial flag threshold (e.g., 50 votes)
     */
    constructor(
        address _feeCollector,
        uint256 _submissionFee,
        uint256 _voteFee,
        uint256 _flagThreshold
    ) Ownable(msg.sender) {
        require(_feeCollector != address(0), "DAOVoting: Invalid fee collector");
        feeCollector = FeeCollector(_feeCollector);
        submissionFee = _submissionFee;
        voteFee = _voteFee;
        flagThreshold = _flagThreshold;
    }

    /**
     * @dev Submit a new proposal
     * @param _title Proposal title
     * @param _description Proposal description
     * @notice Requires payment of submissionFee (10 KAS)
     */
    function submitProposal(
        string memory _title,
        string memory _description
    ) external payable nonReentrant {
        require(msg.value == submissionFee, "DAOVoting: Incorrect submission fee");
        require(bytes(_title).length > 0, "DAOVoting: Title cannot be empty");
        require(bytes(_title).length <= 200, "DAOVoting: Title too long");
        require(bytes(_description).length > 0, "DAOVoting: Description cannot be empty");
        require(bytes(_description).length <= 2000, "DAOVoting: Description too long");

        // Forward fee to treasury
        feeCollector.forwardFee{value: submissionFee}();

        // Create proposal
        proposalCount++;
        uint256 proposalId = proposalCount;

        proposals[proposalId] = Proposal({
            id: proposalId,
            title: _title,
            description: _description,
            proposer: msg.sender,
            submissionFee: submissionFee,
            voteFee: voteFee,
            yesVotes: 0,
            noVotes: 0,
            createdAt: block.timestamp,
            isFlagged: false,
            isActive: true
        });

        emit ProposalSubmitted(proposalId, msg.sender, _title, block.timestamp);
    }

    /**
     * @dev Vote on a proposal
     * @param _proposalId ID of the proposal
     * @param _support true for yes, false for no
     * @notice Requires payment of voteFee (1 KAS)
     */
    function vote(uint256 _proposalId, bool _support) external payable nonReentrant {
        require(_proposalId > 0 && _proposalId <= proposalCount, "DAOVoting: Invalid proposal ID");
        Proposal storage proposal = proposals[_proposalId];
        require(proposal.isActive, "DAOVoting: Proposal is not active");
        require(msg.value == voteFee, "DAOVoting: Incorrect vote fee");

        // Check if user has already voted
        Vote memory existingVote = votes[_proposalId][msg.sender];
        require(existingVote.timestamp == 0, "DAOVoting: Already voted, use changeVote");

        // Forward fee to treasury
        feeCollector.forwardFee{value: voteFee}();

        // Record vote
        votes[_proposalId][msg.sender] = Vote({
            support: _support,
            timestamp: block.timestamp
        });

        // Update vote counts
        if (_support) {
            proposal.yesVotes++;
        } else {
            proposal.noVotes++;
        }

        emit VoteCast(_proposalId, msg.sender, _support, block.timestamp);

        // Auto-flag if threshold reached
        if (proposal.yesVotes >= flagThreshold && !proposal.isFlagged) {
            proposal.isFlagged = true;
            emit ProposalFlagged(_proposalId, proposal.yesVotes, proposal.noVotes, block.timestamp);
        }
    }

    /**
     * @dev Change an existing vote
     * @param _proposalId ID of the proposal
     * @param _newSupport New vote (true for yes, false for no)
     * @notice Requires payment of voteFee (1 KAS)
     */
    function changeVote(uint256 _proposalId, bool _newSupport) external payable nonReentrant {
        require(_proposalId > 0 && _proposalId <= proposalCount, "DAOVoting: Invalid proposal ID");
        Proposal storage proposal = proposals[_proposalId];
        require(proposal.isActive, "DAOVoting: Proposal is not active");
        require(msg.value == voteFee, "DAOVoting: Incorrect vote fee");

        // Check if user has voted
        Vote memory existingVote = votes[_proposalId][msg.sender];
        require(existingVote.timestamp > 0, "DAOVoting: No existing vote to change");
        require(existingVote.support != _newSupport, "DAOVoting: Vote unchanged");

        // Forward fee to treasury
        feeCollector.forwardFee{value: voteFee}();

        // Update vote counts
        if (existingVote.support) {
            proposal.yesVotes--;
        } else {
            proposal.noVotes--;
        }

        if (_newSupport) {
            proposal.yesVotes++;
        } else {
            proposal.noVotes++;
        }

        // Update vote record
        votes[_proposalId][msg.sender] = Vote({
            support: _newSupport,
            timestamp: block.timestamp
        });

        emit VoteChanged(_proposalId, msg.sender, existingVote.support, _newSupport, block.timestamp);

        // Auto-flag if threshold reached
        if (proposal.yesVotes >= flagThreshold && !proposal.isFlagged) {
            proposal.isFlagged = true;
            emit ProposalFlagged(_proposalId, proposal.yesVotes, proposal.noVotes, block.timestamp);
        }
    }

    /**
     * @dev Manually flag a proposal (admin only)
     * @param _proposalId ID of the proposal
     */
    function flagProposal(uint256 _proposalId) external onlyOwner {
        require(_proposalId > 0 && _proposalId <= proposalCount, "DAOVoting: Invalid proposal ID");
        Proposal storage proposal = proposals[_proposalId];
        require(proposal.isActive, "DAOVoting: Proposal is not active");
        require(!proposal.isFlagged, "DAOVoting: Proposal already flagged");

        proposal.isFlagged = true;
        emit ProposalFlagged(_proposalId, proposal.yesVotes, proposal.noVotes, block.timestamp);
    }

    /**
     * @dev Get a single proposal
     * @param _proposalId ID of the proposal
     * @return Proposal struct
     */
    function getProposal(uint256 _proposalId) external view returns (Proposal memory) {
        require(_proposalId > 0 && _proposalId <= proposalCount, "DAOVoting: Invalid proposal ID");
        return proposals[_proposalId];
    }

    /**
     * @dev Get multiple proposals with pagination
     * @param _offset Starting index (0-based)
     * @param _limit Number of proposals to return
     * @return Array of Proposal structs
     */
    function getProposals(
        uint256 _offset,
        uint256 _limit
    ) external view returns (Proposal[] memory) {
        require(_limit > 0 && _limit <= 100, "DAOVoting: Invalid limit");
        require(_offset < proposalCount, "DAOVoting: Invalid offset");

        uint256 end = _offset + _limit;
        if (end > proposalCount) {
            end = proposalCount;
        }

        uint256 count = end - _offset;
        Proposal[] memory result = new Proposal[](count);

        for (uint256 i = 0; i < count; i++) {
            result[i] = proposals[_offset + i + 1]; // proposal IDs start at 1
        }

        return result;
    }

    /**
     * @dev Check if a user has voted on a proposal
     * @param _proposalId ID of the proposal
     * @param _user Address of the user
     * @return true if user has voted
     */
    function hasUserVoted(uint256 _proposalId, address _user) external view returns (bool) {
        require(_proposalId > 0 && _proposalId <= proposalCount, "DAOVoting: Invalid proposal ID");
        return votes[_proposalId][_user].timestamp > 0;
    }

    /**
     * @dev Get a user's vote for a proposal
     * @param _proposalId ID of the proposal
     * @param _user Address of the user
     * @return Vote struct (timestamp will be 0 if no vote)
     */
    function getUserVote(uint256 _proposalId, address _user) external view returns (Vote memory) {
        require(_proposalId > 0 && _proposalId <= proposalCount, "DAOVoting: Invalid proposal ID");
        return votes[_proposalId][_user];
    }

    /**
     * @dev Set submission fee (admin only)
     * @param _newFee New submission fee
     */
    function setSubmissionFee(uint256 _newFee) external onlyOwner {
        uint256 oldFee = submissionFee;
        submissionFee = _newFee;
        emit SubmissionFeeUpdated(oldFee, _newFee);
    }

    /**
     * @dev Set vote fee (admin only)
     * @param _newFee New vote fee
     */
    function setVoteFee(uint256 _newFee) external onlyOwner {
        uint256 oldFee = voteFee;
        voteFee = _newFee;
        emit VoteFeeUpdated(oldFee, _newFee);
    }

    /**
     * @dev Set flag threshold (admin only)
     * @param _newThreshold New flag threshold
     */
    function setFlagThreshold(uint256 _newThreshold) external onlyOwner {
        uint256 oldThreshold = flagThreshold;
        flagThreshold = _newThreshold;
        emit FlagThresholdUpdated(oldThreshold, _newThreshold);
    }

    /**
     * @dev Set fee collector (admin only)
     * @param _feeCollector New fee collector address
     */
    function setFeeCollector(address _feeCollector) external onlyOwner {
        require(_feeCollector != address(0), "DAOVoting: Invalid fee collector");
        address oldCollector = address(feeCollector);
        feeCollector = FeeCollector(_feeCollector);
        emit FeeCollectorUpdated(oldCollector, _feeCollector);
    }
}

contracts/DAppRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title DAppRegistry
 * @dev Registry for tracking deployed dApps and their metadata
 * @notice This contract manages dApp registration and links them to tokens for future Token Builder
 */
contract DAppRegistry is AccessControl {
    // Role for dApp deployers
    bytes32 public constant DEPLOYER_ROLE = keccak256("DEPLOYER_ROLE");

    // dApp structure
    struct DApp {
        string name;
        string version;
        string category;
        address deployer;
        address contractAddress;
        bool isActive;
        uint256 createdAt;
        address tokenAddress; // Token contract address
        string ticker; // Token ticker/symbol
        uint256 totalSupply; // Token total supply
        string ipfsCID; // IPFS CID for metadata
    }

    // Mapping from dApp ID to dApp info
    mapping(uint256 => DApp) public dApps;
    
    // Mapping from contract address to dApp ID
    mapping(address => uint256) public contractToDAppId;
    
    // Mapping from token address to array of dApp IDs
    mapping(address => uint256[]) public tokenToDApps;

    // Counter for dApp IDs
    uint256 public dAppCount;

    // Events
    event DAppRegistered(
        uint256 indexed dAppId,
        string name,
        string version,
        address indexed deployer,
        address indexed contractAddress,
        uint256 timestamp
    );
    event DAppLinkedToToken(
        uint256 indexed dAppId,
        address indexed tokenAddress,
        string ticker,
        uint256 totalSupply,
        uint256 timestamp
    );
    event DAppMetadataUpdated(
        uint256 indexed dAppId,
        string ipfsCID,
        uint256 timestamp
    );
    event DAppStatusUpdated(uint256 indexed dAppId, bool isActive);
    event TokenDAppsUpdated(address indexed tokenAddress, uint256[] dAppIds);

    /**
     * @dev Constructor sets up default admin role
     */
    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(DEPLOYER_ROLE, msg.sender);
    }

    /**
     * @dev Register a new dApp
     * @param _name Name of the dApp
     * @param _version Version of the dApp
     * @param _category Category of the dApp
     * @param _contractAddress Address of the dApp contract
     * @return dAppId The ID of the registered dApp
     */
    function registerDApp(
        string memory _name,
        string memory _version,
        string memory _category,
        address _contractAddress
    ) external onlyRole(DEPLOYER_ROLE) returns (uint256) {
        require(_contractAddress != address(0), "DAppRegistry: Invalid contract address");
        require(bytes(_name).length > 0, "DAppRegistry: Name cannot be empty");
        
        // Check if contract is already registered
        require(
            contractToDAppId[_contractAddress] == 0,
            "DAppRegistry: Contract already registered"
        );

        dAppCount++;
        uint256 dAppId = dAppCount;

        dApps[dAppId] = DApp({
            name: _name,
            version: _version,
            category: _category,
            deployer: msg.sender,
            contractAddress: _contractAddress,
            isActive: true,
            createdAt: block.timestamp,
            tokenAddress: address(0),
            ticker: "",
            totalSupply: 0,
            ipfsCID: ""
        });

        contractToDAppId[_contractAddress] = dAppId;

        emit DAppRegistered(
            dAppId,
            _name,
            _version,
            msg.sender,
            _contractAddress,
            block.timestamp
        );

        return dAppId;
    }

    /**
     * @dev Link a dApp to a token
     * @param _dAppId ID of the dApp
     * @param _tokenAddress Address of the token
     * @param _ticker Token ticker/symbol
     * @param _totalSupply Token total supply
     */
    function linkDAppToToken(
        uint256 _dAppId,
        address _tokenAddress,
        string memory _ticker,
        uint256 _totalSupply
    ) external {
        require(_dAppId > 0 && _dAppId <= dAppCount, "DAppRegistry: Invalid dApp ID");
        require(_tokenAddress != address(0), "DAppRegistry: Invalid token address");
        require(dApps[_dAppId].isActive, "DAppRegistry: dApp is not active");
        
        // Only deployer or admin can link
        require(
            dApps[_dAppId].deployer == msg.sender ||
                hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "DAppRegistry: Not authorized"
        );

        dApps[_dAppId].tokenAddress = _tokenAddress;
        dApps[_dAppId].ticker = _ticker;
        dApps[_dAppId].totalSupply = _totalSupply;
        
        // Add to token's dApp list if not already present
        uint256[] storage tokenDApps = tokenToDApps[_tokenAddress];
        bool exists = false;
        for (uint256 i = 0; i < tokenDApps.length; i++) {
            if (tokenDApps[i] == _dAppId) {
                exists = true;
                break;
            }
        }
        if (!exists) {
            tokenDApps.push(_dAppId);
        }

        emit DAppLinkedToToken(_dAppId, _tokenAddress, _ticker, _totalSupply, block.timestamp);
        emit TokenDAppsUpdated(_tokenAddress, tokenToDApps[_tokenAddress]);
    }
    
    /**
     * @dev Update dApp IPFS metadata CID
     * @param _dAppId ID of the dApp
     * @param _ipfsCID IPFS CID for metadata
     */
    function updateDAppMetadata(uint256 _dAppId, string memory _ipfsCID) external {
        require(_dAppId > 0 && _dAppId <= dAppCount, "DAppRegistry: Invalid dApp ID");
        require(
            dApps[_dAppId].deployer == msg.sender ||
                hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "DAppRegistry: Not authorized"
        );
        
        dApps[_dAppId].ipfsCID = _ipfsCID;
        emit DAppMetadataUpdated(_dAppId, _ipfsCID, block.timestamp);
    }

    /**
     * @dev Update dApp status (active/inactive)
     * @param _dAppId ID of the dApp
     * @param _isActive New status
     */
    function updateDAppStatus(uint256 _dAppId, bool _isActive) external {
        require(_dAppId > 0 && _dAppId <= dAppCount, "DAppRegistry: Invalid dApp ID");
        require(
            dApps[_dAppId].deployer == msg.sender ||
                hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "DAppRegistry: Not authorized"
        );
        dApps[_dAppId].isActive = _isActive;
        emit DAppStatusUpdated(_dAppId, _isActive);
    }

    /**
     * @dev Get dApp information
     * @param _dAppId ID of the dApp
     * @return DApp struct with all information
     */
    function getDApp(uint256 _dAppId) external view returns (DApp memory) {
        require(_dAppId > 0 && _dAppId <= dAppCount, "DAppRegistry: Invalid dApp ID");
        return dApps[_dAppId];
    }
    
    /**
     * @dev Get dApp token address
     * @param _dAppId ID of the dApp
     * @return Token address (address(0) if not linked)
     */
    function getDAppToken(uint256 _dAppId) external view returns (address) {
        require(_dAppId > 0 && _dAppId <= dAppCount, "DAppRegistry: Invalid dApp ID");
        return dApps[_dAppId].tokenAddress;
    }

    /**
     * @dev Get all dApp IDs linked to a token
     * @param _tokenAddress Address of the token
     * @return Array of dApp IDs
     */
    function getTokenDApps(address _tokenAddress)
        external
        view
        returns (uint256[] memory)
    {
        return tokenToDApps[_tokenAddress];
    }

    /**
     * @dev Get dApp ID by contract address
     * @param _contractAddress Address of the dApp contract
     * @return dAppId The ID of the dApp, 0 if not found
     */
    function getDAppIdByContract(address _contractAddress)
        external
        view
        returns (uint256)
    {
        return contractToDAppId[_contractAddress];
    }
}

contracts/DAppSubscription.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "./Treasury.sol";
import "./AuthorizationRegistry.sol";
import "./DAppRegistry.sol";

/**
 * @title DAppSubscription
 * @dev Per-dApp subscription contract with developer-configurable rates and flexible frequencies
 * @notice Developers can set their own subscription prices and payment frequencies
 */
contract DAppSubscription is Ownable, AccessControl, ReentrancyGuard {
    // Role for dApp developers
    bytes32 public constant DEVELOPER_ROLE = keccak256("DEVELOPER_ROLE");

    // Treasury contract for fee collection
    Treasury public treasury;

    // AuthorizationRegistry contract for checking developer assignments
    AuthorizationRegistry public authorizationRegistry;

    // DAppRegistry contract for getting dApp IDs
    DAppRegistry public dAppRegistry;

    // Kasparex fee percentage (basis points, e.g., 1500 = 15%)
    uint256 public kasparexFeePercentage;

    // Payment frequency types
    enum PaymentFrequency {
        Monthly,    // 30 days
        Quarterly, // 90 days
        Yearly     // 365 days
    }

    // Subscription plan for a dApp
    struct SubscriptionPlan {
        address dAppContract; // Address of the dApp contract
        address developer; // Developer address
        uint256 monthlyPrice; // Base monthly price in wei
        uint256 quarterlyPrice; // Quarterly price in wei
        uint256 yearlyPrice; // Yearly price in wei
        bool isActive; // Whether plan is active
        uint256 createdAt; // When plan was created
    }

    // User subscription to a specific dApp
    struct UserSubscription {
        uint256 expiryTimestamp; // When subscription expires (0 = never subscribed)
        PaymentFrequency frequency; // Payment frequency used
        bool isActive; // Whether subscription is active
    }

    // Mapping from dApp contract address to subscription plan
    mapping(address => SubscriptionPlan) public subscriptionPlans;

    // Mapping from user address to dApp contract address to subscription
    mapping(address => mapping(address => UserSubscription)) public userSubscriptions;

    // Mapping from dApp contract to array of subscribers
    mapping(address => address[]) public dAppSubscribers;

    // Events
    event SubscriptionPlanCreated(
        address indexed dAppContract,
        address indexed developer,
        uint256 monthlyPrice,
        uint256 quarterlyPrice,
        uint256 yearlyPrice,
        uint256 timestamp
    );
    event SubscriptionPlanUpdated(
        address indexed dAppContract,
        uint256 monthlyPrice,
        uint256 quarterlyPrice,
        uint256 yearlyPrice,
        uint256 timestamp
    );
    event SubscriptionPurchased(
        address indexed user,
        address indexed dAppContract,
        PaymentFrequency frequency,
        uint256 amount,
        uint256 expiryTimestamp,
        uint256 timestamp
    );
    event SubscriptionRenewed(
        address indexed user,
        address indexed dAppContract,
        PaymentFrequency frequency,
        uint256 amount,
        uint256 newExpiryTimestamp,
        uint256 timestamp
    );
    event SubscriptionExpired(
        address indexed user,
        address indexed dAppContract,
        uint256 timestamp
    );
    event KasparexFeePercentageUpdated(uint256 oldPercentage, uint256 newPercentage);
    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);

    /**
     * @dev Constructor sets initial values
     * @param _treasury Address of the Treasury contract
     * @param _authorizationRegistry Address of the AuthorizationRegistry contract
     * @param _dAppRegistry Address of the DAppRegistry contract
     * @param _kasparexFeePercentage Kasparex fee percentage in basis points (default: 1500 = 15%)
     */
    constructor(
        address _treasury,
        address _authorizationRegistry,
        address _dAppRegistry,
        uint256 _kasparexFeePercentage
    ) Ownable(msg.sender) {
        require(_treasury != address(0), "DAppSubscription: Invalid treasury address");
        require(_authorizationRegistry != address(0), "DAppSubscription: Invalid authorization registry address");
        require(_dAppRegistry != address(0), "DAppSubscription: Invalid dApp registry address");
        require(_kasparexFeePercentage <= 10000, "DAppSubscription: Fee cannot exceed 100%");

        treasury = Treasury(_treasury);
        authorizationRegistry = AuthorizationRegistry(_authorizationRegistry);
        dAppRegistry = DAppRegistry(_dAppRegistry);
        kasparexFeePercentage = _kasparexFeePercentage;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    /**
     * @dev Create a subscription plan for a dApp (developer only)
     * @param _dAppContract Address of the dApp contract
     * @param _monthlyPrice Monthly subscription price in wei
     * @param _quarterlyPrice Quarterly subscription price in wei
     * @param _yearlyPrice Yearly subscription price in wei
     */
    function createSubscriptionPlan(
        address _dAppContract,
        uint256 _monthlyPrice,
        uint256 _quarterlyPrice,
        uint256 _yearlyPrice
    ) external {
        require(_dAppContract != address(0), "DAppSubscription: Invalid dApp contract");
        
        // Check if user is authorized: admin, has DEVELOPER_ROLE, or is assigned developer via AuthorizationRegistry
        bool isAuthorized = hasRole(DEFAULT_ADMIN_ROLE, msg.sender) || hasRole(DEVELOPER_ROLE, msg.sender);
        
        // If not authorized via roles, check AuthorizationRegistry
        if (!isAuthorized) {
            uint256 dAppId = dAppRegistry.getDAppIdByContract(_dAppContract);
            if (dAppId > 0) {
                isAuthorized = authorizationRegistry.isDeveloper(dAppId, msg.sender);
            }
        }
        
        require(isAuthorized, "DAppSubscription: Not authorized");
        require(_monthlyPrice > 0, "DAppSubscription: Monthly price must be greater than 0");
        require(_quarterlyPrice > 0, "DAppSubscription: Quarterly price must be greater than 0");
        require(_yearlyPrice > 0, "DAppSubscription: Yearly price must be greater than 0");

        subscriptionPlans[_dAppContract] = SubscriptionPlan({
            dAppContract: _dAppContract,
            developer: msg.sender,
            monthlyPrice: _monthlyPrice,
            quarterlyPrice: _quarterlyPrice,
            yearlyPrice: _yearlyPrice,
            isActive: true,
            createdAt: block.timestamp
        });

        emit SubscriptionPlanCreated(
            _dAppContract,
            msg.sender,
            _monthlyPrice,
            _quarterlyPrice,
            _yearlyPrice,
            block.timestamp
        );
    }

    /**
     * @dev Update subscription plan prices (developer or admin only)
     * @param _dAppContract Address of the dApp contract
     * @param _monthlyPrice New monthly price in wei
     * @param _quarterlyPrice New quarterly price in wei
     * @param _yearlyPrice New yearly price in wei
     */
    function updateSubscriptionPlan(
        address _dAppContract,
        uint256 _monthlyPrice,
        uint256 _quarterlyPrice,
        uint256 _yearlyPrice
    ) external {
        SubscriptionPlan storage plan = subscriptionPlans[_dAppContract];
        require(plan.dAppContract != address(0), "DAppSubscription: Plan does not exist");
        
        // Check if user is authorized: original developer, admin, or assigned developer via AuthorizationRegistry
        bool isAuthorized = plan.developer == msg.sender || hasRole(DEFAULT_ADMIN_ROLE, msg.sender);
        
        // If not authorized, check AuthorizationRegistry
        if (!isAuthorized) {
            uint256 dAppId = dAppRegistry.getDAppIdByContract(_dAppContract);
            if (dAppId > 0) {
                isAuthorized = authorizationRegistry.isDeveloper(dAppId, msg.sender);
            }
        }
        
        require(isAuthorized, "DAppSubscription: Not authorized");
        require(_monthlyPrice > 0, "DAppSubscription: Monthly price must be greater than 0");
        require(_quarterlyPrice > 0, "DAppSubscription: Quarterly price must be greater than 0");
        require(_yearlyPrice > 0, "DAppSubscription: Yearly price must be greater than 0");

        plan.monthlyPrice = _monthlyPrice;
        plan.quarterlyPrice = _quarterlyPrice;
        plan.yearlyPrice = _yearlyPrice;

        emit SubscriptionPlanUpdated(
            _dAppContract,
            _monthlyPrice,
            _quarterlyPrice,
            _yearlyPrice,
            block.timestamp
        );
    }

    /**
     * @dev Subscribe to a dApp with specified payment frequency
     * @param _dAppContract Address of the dApp contract
     * @param _frequency Payment frequency (Monthly, Quarterly, or Yearly)
     */
    function subscribe(
        address _dAppContract,
        PaymentFrequency _frequency
    ) external payable nonReentrant {
        SubscriptionPlan memory plan = subscriptionPlans[_dAppContract];
        require(plan.dAppContract != address(0), "DAppSubscription: Plan does not exist");
        require(plan.isActive, "DAppSubscription: Plan is not active");

        uint256 price;
        uint256 period;

        if (_frequency == PaymentFrequency.Monthly) {
            price = plan.monthlyPrice;
            period = 30 days;
        } else if (_frequency == PaymentFrequency.Quarterly) {
            price = plan.quarterlyPrice;
            period = 90 days;
        } else if (_frequency == PaymentFrequency.Yearly) {
            price = plan.yearlyPrice;
            period = 365 days;
        } else {
            revert("DAppSubscription: Invalid frequency");
        }

        require(msg.value >= price, "DAppSubscription: Insufficient payment");

        uint256 kasparexFee = (msg.value * kasparexFeePercentage) / 10000;
        uint256 developerAmount = msg.value - kasparexFee;

        // Send Kasparex fee to treasury
        if (kasparexFee > 0) {
            treasury.collectFee{value: kasparexFee}();
        }

        // Send developer amount (net after fee)
        if (developerAmount > 0) {
            (bool success, ) = payable(plan.developer).call{value: developerAmount}("");
            require(success, "DAppSubscription: Developer transfer failed");
        }

        // Calculate new expiry timestamp
        UserSubscription storage userSub = userSubscriptions[msg.sender][_dAppContract];
        uint256 currentExpiry = userSub.expiryTimestamp;
        uint256 newExpiry;

        if (currentExpiry > block.timestamp) {
            // Renew existing active subscription
            newExpiry = currentExpiry + period;
            emit SubscriptionRenewed(
                msg.sender,
                _dAppContract,
                _frequency,
                msg.value,
                newExpiry,
                block.timestamp
            );
        } else {
            // New subscription
            newExpiry = block.timestamp + period;
            emit SubscriptionPurchased(
                msg.sender,
                _dAppContract,
                _frequency,
                msg.value,
                newExpiry,
                block.timestamp
            );

            // Add to subscribers list if not already there
            bool exists = false;
            for (uint256 i = 0; i < dAppSubscribers[_dAppContract].length; i++) {
                if (dAppSubscribers[_dAppContract][i] == msg.sender) {
                    exists = true;
                    break;
                }
            }
            if (!exists) {
                dAppSubscribers[_dAppContract].push(msg.sender);
            }
        }

        userSub.expiryTimestamp = newExpiry;
        userSub.frequency = _frequency;
        userSub.isActive = true;

        // Refund excess payment
        if (msg.value > price) {
            uint256 refund = msg.value - price;
            (bool success, ) = payable(msg.sender).call{value: refund}("");
            require(success, "DAppSubscription: Refund failed");
        }
    }

    /**
     * @dev Check if a user is subscribed to a specific dApp
     * @param _user User address
     * @param _dAppContract dApp contract address
     * @return bool True if subscribed and active
     */
    function isSubscribed(address _user, address _dAppContract) external view returns (bool) {
        UserSubscription memory sub = userSubscriptions[_user][_dAppContract];
        if (!sub.isActive) return false;
        return block.timestamp <= sub.expiryTimestamp;
    }

    /**
     * @dev Get subscription expiry timestamp for a user and dApp
     * @param _user User address
     * @param _dAppContract dApp contract address
     * @return uint256 Expiry timestamp (0 if not subscribed)
     */
    function getExpiryTimestamp(
        address _user,
        address _dAppContract
    ) external view returns (uint256) {
        return userSubscriptions[_user][_dAppContract].expiryTimestamp;
    }

    /**
     * @dev Get subscription plan for a dApp
     * @param _dAppContract dApp contract address
     * @return SubscriptionPlan The subscription plan
     */
    function getSubscriptionPlan(
        address _dAppContract
    ) external view returns (SubscriptionPlan memory) {
        return subscriptionPlans[_dAppContract];
    }

    /**
     * @dev Get all subscribers for a dApp
     * @param _dAppContract dApp contract address
     * @return address[] Array of subscriber addresses
     */
    function getSubscribers(address _dAppContract) external view returns (address[] memory) {
        return dAppSubscribers[_dAppContract];
    }

    /**
     * @dev Update Kasparex fee percentage (only owner)
     * @param _newPercentage New fee percentage in basis points
     */
    function setKasparexFeePercentage(uint256 _newPercentage) external onlyOwner {
        require(_newPercentage <= 10000, "DAppSubscription: Fee cannot exceed 100%");
        uint256 oldPercentage = kasparexFeePercentage;
        kasparexFeePercentage = _newPercentage;
        emit KasparexFeePercentageUpdated(oldPercentage, _newPercentage);
    }

    /**
     * @dev Update Treasury contract address (only owner)
     * @param _treasury New Treasury contract address
     */
    function setTreasury(address _treasury) external onlyOwner {
        require(_treasury != address(0), "DAppSubscription: Invalid treasury address");
        address oldTreasury = address(treasury);
        treasury = Treasury(_treasury);
        emit TreasuryUpdated(oldTreasury, _treasury);
    }

    /**
     * @dev Update AuthorizationRegistry contract address (only owner)
     * @param _authorizationRegistry New AuthorizationRegistry contract address
     */
    function setAuthorizationRegistry(address _authorizationRegistry) external onlyOwner {
        require(_authorizationRegistry != address(0), "DAppSubscription: Invalid authorization registry address");
        authorizationRegistry = AuthorizationRegistry(_authorizationRegistry);
    }

    /**
     * @dev Update DAppRegistry contract address (only owner)
     * @param _dAppRegistry New DAppRegistry contract address
     */
    function setDAppRegistry(address _dAppRegistry) external onlyOwner {
        require(_dAppRegistry != address(0), "DAppSubscription: Invalid dApp registry address");
        dAppRegistry = DAppRegistry(_dAppRegistry);
    }

    /**
     * @dev Deactivate a subscription plan (developer or admin only)
     * @param _dAppContract dApp contract address
     */
    function deactivatePlan(address _dAppContract) external {
        SubscriptionPlan storage plan = subscriptionPlans[_dAppContract];
        
        // Check if user is authorized: original developer, admin, or assigned developer via AuthorizationRegistry
        bool isAuthorized = plan.developer == msg.sender || hasRole(DEFAULT_ADMIN_ROLE, msg.sender);
        
        // If not authorized, check AuthorizationRegistry
        if (!isAuthorized) {
            uint256 dAppId = dAppRegistry.getDAppIdByContract(_dAppContract);
            if (dAppId > 0) {
                isAuthorized = authorizationRegistry.isDeveloper(dAppId, msg.sender);
            }
        }
        
        require(isAuthorized, "DAppSubscription: Not authorized");
        plan.isActive = false;
    }

    /**
     * @dev Deactivate a user subscription (admin only)
     * @param _user User address
     * @param _dAppContract dApp contract address
     */
    function deactivateUserSubscription(
        address _user,
        address _dAppContract
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        UserSubscription storage sub = userSubscriptions[_user][_dAppContract];
        if (sub.isActive) {
            sub.isActive = false;
            emit SubscriptionExpired(_user, _dAppContract, block.timestamp);
        }
    }

    /**
     * @dev Grant developer role to an address
     * @param _developer Address to grant role to
     */
    function grantDeveloperRole(address _developer) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(DEVELOPER_ROLE, _developer);
    }

    /**
     * @dev Revoke developer role from an address
     * @param _developer Address to revoke role from
     */
    function revokeDeveloperRole(address _developer) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(DEVELOPER_ROLE, _developer);
    }
}

contracts/DAppToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title DAppToken
 * @dev Standardized ERC-20 token for dApps with fixed allocation
 * @notice Allocation: 80% Use-to-mint, 10% Liquidity, 5% Treasury, 3% Dev, 2% Airdrops
 */
contract DAppToken is ERC20, Ownable, ReentrancyGuard {
    // Fixed total supply (e.g., 1M tokens)
    uint256 public immutable MAX_SUPPLY;
    
    // Allocation percentages (basis points, 10000 = 100%)
    uint256 public constant USE_TO_MINT_PERCENTAGE = 8000; // 80%
    uint256 public constant LIQUIDITY_PERCENTAGE = 1000;   // 10%
    uint256 public constant TREASURY_PERCENTAGE = 500;     // 5%
    uint256 public constant DEV_PERCENTAGE = 300;          // 3%
    uint256 public constant AIRDROP_PERCENTAGE = 200;      // 2%
    
    // Allocation addresses
    address public rewardVault;      // 80% - Use-to-mint rewards
    address public liquidityReserve; // 10% - Locked until DEX
    address public treasury;         // 5% - Kasparex + Project
    address public devAddress;       // 3% - Dev/maintenance
    address public airdropAddress;   // 2% - Airdrops & bonuses
    
    // Minting control
    address public minter; // RewardManager or ProofOfUtility contract
    bool public mintingEnabled = true;
    bool public burnEnabled = false;
    
    // Events
    event MinterUpdated(address indexed oldMinter, address indexed newMinter);
    event MintingToggled(bool enabled);
    event BurnToggled(bool enabled);
    event AllocationDistributed(
        address rewardVault,
        address liquidityReserve,
        address treasury,
        address devAddress,
        address airdropAddress
    );
    
    /**
     * @dev Constructor sets up token with fixed supply and allocation
     * @param _name Token name
     * @param _symbol Token symbol
     * @param _maxSupply Maximum supply (e.g., 1_000_000 * 10^18)
     * @param _rewardVault Address for use-to-mint rewards
     * @param _liquidityReserve Address for liquidity reserve
     * @param _treasury Address for treasury
     * @param _devAddress Address for dev/maintenance
     * @param _airdropAddress Address for airdrops
     */
    constructor(
        string memory _name,
        string memory _symbol,
        uint256 _maxSupply,
        address _rewardVault,
        address _liquidityReserve,
        address _treasury,
        address _devAddress,
        address _airdropAddress
    ) ERC20(_name, _symbol) Ownable(msg.sender) {
        require(_maxSupply > 0, "DAppToken: Invalid max supply");
        require(_rewardVault != address(0), "DAppToken: Invalid reward vault");
        require(_liquidityReserve != address(0), "DAppToken: Invalid liquidity reserve");
        require(_treasury != address(0), "DAppToken: Invalid treasury");
        require(_devAddress != address(0), "DAppToken: Invalid dev address");
        require(_airdropAddress != address(0), "DAppToken: Invalid airdrop address");
        
        MAX_SUPPLY = _maxSupply;
        rewardVault = _rewardVault;
        liquidityReserve = _liquidityReserve;
        treasury = _treasury;
        devAddress = _devAddress;
        airdropAddress = _airdropAddress;
        
        // Distribute initial allocation
        _distributeAllocation();
    }
    
    /**
     * @dev Distribute tokens according to allocation percentages
     */
    function _distributeAllocation() internal {
        uint256 useToMint = (MAX_SUPPLY * USE_TO_MINT_PERCENTAGE) / 10000;
        uint256 liquidity = (MAX_SUPPLY * LIQUIDITY_PERCENTAGE) / 10000;
        uint256 treasuryAmount = (MAX_SUPPLY * TREASURY_PERCENTAGE) / 10000;
        uint256 devAmount = (MAX_SUPPLY * DEV_PERCENTAGE) / 10000;
        uint256 airdropAmount = MAX_SUPPLY - useToMint - liquidity - treasuryAmount - devAmount; // Remainder for airdrops
        
        _mint(rewardVault, useToMint);
        _mint(liquidityReserve, liquidity);
        _mint(treasury, treasuryAmount);
        _mint(devAddress, devAmount);
        _mint(airdropAddress, airdropAmount);
        
        emit AllocationDistributed(
            rewardVault,
            liquidityReserve,
            treasury,
            devAddress,
            airdropAddress
        );
    }
    
    /**
     * @dev Mint tokens (only by minter)
     * @param to Address to mint to
     * @param amount Amount to mint
     */
    function mint(address to, uint256 amount) external {
        require(msg.sender == minter, "DAppToken: Only minter can mint");
        require(mintingEnabled, "DAppToken: Minting disabled");
        require(totalSupply() + amount <= MAX_SUPPLY, "DAppToken: Exceeds max supply");
        
        _mint(to, amount);
    }
    
    /**
     * @dev Burn tokens (if enabled)
     * @param amount Amount to burn
     */
    function burn(uint256 amount) external {
        require(burnEnabled, "DAppToken: Burning disabled");
        _burn(msg.sender, amount);
    }
    
    /**
     * @dev Set minter address (only owner)
     * @param _minter New minter address
     */
    function setMinter(address _minter) external onlyOwner {
        require(_minter != address(0), "DAppToken: Invalid minter");
        address oldMinter = minter;
        minter = _minter;
        emit MinterUpdated(oldMinter, _minter);
    }
    
    /**
     * @dev Toggle minting (only owner)
     * @param _enabled Whether minting is enabled
     */
    function setMintingEnabled(bool _enabled) external onlyOwner {
        mintingEnabled = _enabled;
        emit MintingToggled(_enabled);
    }
    
    /**
     * @dev Enable burning after full emission (only owner)
     * @param _enabled Whether burning is enabled
     */
    function setBurnEnabled(bool _enabled) external onlyOwner {
        burnEnabled = _enabled;
        emit BurnToggled(_enabled);
    }
    
    /**
     * @dev Get remaining mintable supply
     */
    function getRemainingSupply() external view returns (uint256) {
        return MAX_SUPPLY - totalSupply();
    }
}

contracts/FeeCollector.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./Treasury.sol";

/**
 * @title FeeCollector
 * @dev Interface contract for dApps to send fees to Treasury
 * @notice Provides a simple interface for collecting fees from dApp transactions
 */
contract FeeCollector is Ownable {
    // Treasury contract address
    Treasury public treasury;

    // Events
    event FeeForwarded(address indexed from, uint256 amount, uint256 timestamp);
    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);

    /**
     * @dev Constructor sets the Treasury contract address
     * @param _treasury Address of the Treasury contract
     */
    constructor(address _treasury) Ownable(msg.sender) {
        require(_treasury != address(0), "FeeCollector: Invalid treasury address");
        treasury = Treasury(_treasury);
    }

    /**
     * @dev Forward fees to Treasury
     * @notice This function receives fees and forwards them to the Treasury contract
     */
    function forwardFee() external payable {
        require(msg.value > 0, "FeeCollector: Fee must be greater than 0");
        treasury.collectFee{value: msg.value}();
        emit FeeForwarded(msg.sender, msg.value, block.timestamp);
    }

    /**
     * @dev Update Treasury contract address
     * @param _treasury New Treasury contract address
     */
    function setTreasury(address _treasury) external onlyOwner {
        require(_treasury != address(0), "FeeCollector: Invalid treasury address");
        address oldTreasury = address(treasury);
        treasury = Treasury(_treasury);
        emit TreasuryUpdated(oldTreasury, _treasury);
    }
}

contracts/FeeHandler.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title FeeHandler
 * @dev Handles KAS fee splitting (60% Kasparex, 40% Project)
 * @notice Receives fees from dApp actions and distributes them
 */
contract FeeHandler is Ownable, ReentrancyGuard {
    // Treasury addresses
    address public kasparexTreasury;
    address public projectTreasury;
    
    // Split percentages (basis points, 10000 = 100%)
    uint256 public constant KASPAREX_PERCENTAGE = 6000; // 60%
    uint256 public constant PROJECT_PERCENTAGE = 4000;  // 40%
    
    // Fee tracking
    uint256 public totalFeesCollected;
    mapping(address => uint256) public projectFees; // Track fees per project
    
    // Events
    event FeeReceived(
        address indexed from,
        address indexed projectTreasury,
        uint256 totalAmount,
        uint256 kasparexAmount,
        uint256 projectAmount,
        uint256 timestamp
    );
    event TreasuryUpdated(
        address indexed oldKasparexTreasury,
        address indexed newKasparexTreasury,
        address oldProjectTreasury,
        address newProjectTreasury
    );
    
    /**
     * @dev Constructor
     * @param _kasparexTreasury Kasparex treasury address
     * @param _projectTreasury Default project treasury address
     */
    constructor(address _kasparexTreasury, address _projectTreasury) Ownable(msg.sender) {
        require(_kasparexTreasury != address(0), "FeeHandler: Invalid Kasparex treasury");
        require(_projectTreasury != address(0), "FeeHandler: Invalid project treasury");
        
        kasparexTreasury = _kasparexTreasury;
        projectTreasury = _projectTreasury;
    }
    
    /**
     * @dev Receive fees and split them
     * @param _projectTreasury Project treasury address (if different from default)
     */
    function collectFee(address _projectTreasury) external payable nonReentrant {
        require(msg.value > 0, "FeeHandler: Fee must be greater than 0");
        
        address projectTreasury_ = _projectTreasury != address(0) 
            ? _projectTreasury 
            : projectTreasury;
        
        // Calculate splits
        uint256 kasparexAmount = (msg.value * KASPAREX_PERCENTAGE) / 10000;
        uint256 projectAmount = msg.value - kasparexAmount; // Remainder to project
        
        totalFeesCollected += msg.value;
        projectFees[projectTreasury_] += projectAmount;
        
        // Transfer to treasuries
        (bool kasparexSuccess, ) = payable(kasparexTreasury).call{value: kasparexAmount}("");
        require(kasparexSuccess, "FeeHandler: Kasparex transfer failed");
        
        (bool projectSuccess, ) = payable(projectTreasury_).call{value: projectAmount}("");
        require(projectSuccess, "FeeHandler: Project transfer failed");
        
        emit FeeReceived(
            msg.sender,
            projectTreasury_,
            msg.value,
            kasparexAmount,
            projectAmount,
            block.timestamp
        );
    }
    
    /**
     * @dev Batch collect fees (gas optimization)
     * @param _projectTreasuries Array of project treasury addresses
     */
    function collectFeesBatch(address[] memory _projectTreasuries) external payable nonReentrant {
        require(msg.value > 0, "FeeHandler: Fee must be greater than 0");
        require(_projectTreasuries.length > 0, "FeeHandler: Empty project treasuries");
        
        uint256 feePerProject = msg.value / _projectTreasuries.length;
        uint256 kasparexAmount = (msg.value * KASPAREX_PERCENTAGE) / 10000;
        uint256 totalProjectAmount = msg.value - kasparexAmount;
        uint256 projectAmountPerTreasury = totalProjectAmount / _projectTreasuries.length;
        
        totalFeesCollected += msg.value;
        
        // Transfer to Kasparex treasury
        (bool kasparexSuccess, ) = payable(kasparexTreasury).call{value: kasparexAmount}("");
        require(kasparexSuccess, "FeeHandler: Kasparex transfer failed");
        
        // Transfer to each project treasury
        for (uint256 i = 0; i < _projectTreasuries.length; i++) {
            if (_projectTreasuries[i] != address(0)) {
                projectFees[_projectTreasuries[i]] += projectAmountPerTreasury;
                (bool success, ) = payable(_projectTreasuries[i]).call{value: projectAmountPerTreasury}("");
                require(success, "FeeHandler: Project transfer failed");
            }
        }
    }
    
    /**
     * @dev Update treasury addresses (only owner)
     * @param _kasparexTreasury New Kasparex treasury address
     * @param _projectTreasury New default project treasury address
     */
    function setTreasuries(address _kasparexTreasury, address _projectTreasury) external onlyOwner {
        require(_kasparexTreasury != address(0), "FeeHandler: Invalid Kasparex treasury");
        require(_projectTreasury != address(0), "FeeHandler: Invalid project treasury");
        
        address oldKasparex = kasparexTreasury;
        address oldProject = projectTreasury;
        
        kasparexTreasury = _kasparexTreasury;
        projectTreasury = _projectTreasury;
        
        emit TreasuryUpdated(oldKasparex, _kasparexTreasury, oldProject, _projectTreasury);
    }
    
    /**
     * @dev Get total fees collected for a project
     * @param _projectTreasury Project treasury address
     * @return Total fees collected
     */
    function getProjectFees(address _projectTreasury) external view returns (uint256) {
        return projectFees[_projectTreasury];
    }
}

contracts/GRIDToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title GRIDToken
 * @dev GRID token - Global Reward and Incentive Distribution token
 * @notice Fixed max supply (10B GRID), deflationary (burns on conversion/spend)
 */
contract GRIDToken is ERC20, Ownable, ReentrancyGuard {
    // Fixed max supply: 10B GRID
    uint256 public constant MAX_SUPPLY = 10_000_000_000 * 10**18;
    
    // Reward vault for pre-minted tokens
    address public rewardVault;
    
    // Burn tracking
    uint256 public totalBurned;
    
    // Events
    event TokensBurned(address indexed from, uint256 amount);
    event RewardVaultUpdated(address indexed oldVault, address indexed newVault);
    
    /**
     * @dev Constructor pre-mints all tokens to reward vault
     * @param _rewardVault Address to receive pre-minted tokens
     */
    constructor(address _rewardVault) ERC20("GRID Token", "GRID") Ownable(msg.sender) {
        require(_rewardVault != address(0), "GRIDToken: Invalid reward vault");
        rewardVault = _rewardVault;
        
        // Pre-mint all tokens to reward vault
        _mint(_rewardVault, MAX_SUPPLY);
    }
    
    /**
     * @dev Burn tokens (deflationary mechanism)
     * @param amount Amount to burn
     */
    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
        totalBurned += amount;
        emit TokensBurned(msg.sender, amount);
    }
    
    /**
     * @dev Burn tokens from a specific address (for conversions)
     * @param from Address to burn from
     * @param amount Amount to burn
     */
    function burnFrom(address from, uint256 amount) external {
        _spendAllowance(from, msg.sender, amount);
        _burn(from, amount);
        totalBurned += amount;
        emit TokensBurned(from, amount);
    }
    
    /**
     * @dev Update reward vault address (only owner)
     * @param _rewardVault New reward vault address
     */
    function setRewardVault(address _rewardVault) external onlyOwner {
        require(_rewardVault != address(0), "GRIDToken: Invalid reward vault");
        address oldVault = rewardVault;
        rewardVault = _rewardVault;
        emit RewardVaultUpdated(oldVault, _rewardVault);
    }
    
    /**
     * @dev Get circulating supply (total supply - burned)
     */
    function circulatingSupply() external view returns (uint256) {
        return totalSupply() - totalBurned;
    }
    
    /**
     * @dev Get burn percentage of max supply
     */
    function burnPercentage() external view returns (uint256) {
        if (MAX_SUPPLY == 0) return 0;
        return (totalBurned * 10000) / MAX_SUPPLY; // Basis points
    }
}

contracts/LoyaltyPoints.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title LoyaltyPoints
 * @dev Long-term participation tracking (soulbound-like, non-transferable)
 * @notice Tracks user participation, convertible to GRID/KREX later
 */
contract LoyaltyPoints is Ownable {
    // Loyalty point structure
    struct LoyaltyData {
        uint256 totalPoints;
        uint256 participationDays;
        uint256 lastActivity;
        uint256 streakDays;
    }
    
    // User loyalty data
    mapping(address => LoyaltyData) public userLoyalty;
    
    // Points per action type
    mapping(string => uint256) public actionPoints; // actionType -> points
    
    // Minimum activity interval for streak (in seconds, default 1 day)
    uint256 public streakInterval = 86400;
    
    // Events
    event PointsAwarded(
        address indexed user,
        string actionType,
        uint256 points,
        uint256 totalPoints,
        uint256 timestamp
    );
    event StreakUpdated(address indexed user, uint256 streakDays, uint256 timestamp);
    event ActionPointsUpdated(string actionType, uint256 oldPoints, uint256 newPoints);
    
    /**
     * @dev Constructor
     */
    constructor() Ownable(msg.sender) {
        // Set default action points
        actionPoints["vote"] = 10;
        actionPoints["proposal"] = 50;
        actionPoints["payment"] = 5;
        actionPoints["daily_login"] = 1;
    }
    
    /**
     * @dev Award loyalty points for an action
     * @param user User address
     * @param actionType Type of action performed
     */
    function awardPoints(address user, string memory actionType) external {
        require(user != address(0), "LoyaltyPoints: Invalid user");
        
        uint256 points = actionPoints[actionType];
        if (points == 0) {
            return; // No points for this action
        }
        
        LoyaltyData storage loyalty = userLoyalty[user];
        loyalty.totalPoints += points;
        loyalty.lastActivity = block.timestamp;
        
        // Update participation days
        uint256 daysSinceLastActivity = (block.timestamp - loyalty.lastActivity) / streakInterval;
        if (daysSinceLastActivity >= 1) {
            loyalty.participationDays++;
            
            // Update streak
            if (daysSinceLastActivity == 1) {
                loyalty.streakDays++;
            } else {
                loyalty.streakDays = 1; // Reset streak
            }
            
            emit StreakUpdated(user, loyalty.streakDays, block.timestamp);
        }
        
        emit PointsAwarded(user, actionType, points, loyalty.totalPoints, block.timestamp);
    }
    
    /**
     * @dev Batch award points (gas optimization)
     * @param users Array of user addresses
     * @param actionTypes Array of action types
     */
    function awardPointsBatch(address[] memory users, string[] memory actionTypes) external {
        require(users.length == actionTypes.length, "LoyaltyPoints: Array length mismatch");
        
        for (uint256 i = 0; i < users.length; i++) {
            // Inline the awardPoints logic to avoid function call overhead
            address user = users[i];
            string memory actionType = actionTypes[i];
            
            require(user != address(0), "LoyaltyPoints: Invalid user");
            
            uint256 points = actionPoints[actionType];
            if (points == 0) {
                continue; // No points for this action
            }
            
            LoyaltyData storage loyalty = userLoyalty[user];
            loyalty.totalPoints += points;
            loyalty.lastActivity = block.timestamp;
            
            // Update participation days
            uint256 daysSinceLastActivity = (block.timestamp - loyalty.lastActivity) / streakInterval;
            if (daysSinceLastActivity >= 1) {
                loyalty.participationDays++;
                
                // Update streak
                if (daysSinceLastActivity == 1) {
                    loyalty.streakDays++;
                } else {
                    loyalty.streakDays = 1; // Reset streak
                }
                
                emit StreakUpdated(user, loyalty.streakDays, block.timestamp);
            }
            
            emit PointsAwarded(user, actionType, points, loyalty.totalPoints, block.timestamp);
        }
    }
    
    /**
     * @dev Get user's loyalty data
     * @param user User address
     * @return LoyaltyData struct
     */
    function getUserLoyalty(address user) external view returns (LoyaltyData memory) {
        return userLoyalty[user];
    }
    
    /**
     * @dev Get user's total points
     * @param user User address
     * @return Total points
     */
    function getTotalPoints(address user) external view returns (uint256) {
        return userLoyalty[user].totalPoints;
    }
    
    /**
     * @dev Get user's streak
     * @param user User address
     * @return Streak days
     */
    function getStreak(address user) external view returns (uint256) {
        return userLoyalty[user].streakDays;
    }
    
    /**
     * @dev Set points for an action type (only owner)
     * @param actionType Action type
     * @param points Points to award
     */
    function setActionPoints(string memory actionType, uint256 points) external onlyOwner {
        uint256 oldPoints = actionPoints[actionType];
        actionPoints[actionType] = points;
        emit ActionPointsUpdated(actionType, oldPoints, points);
    }
    
    /**
     * @dev Update streak interval (only owner)
     * @param _interval New interval in seconds
     */
    function setStreakInterval(uint256 _interval) external onlyOwner {
        streakInterval = _interval;
    }
}

contracts/PlatformSubscription.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./Treasury.sol";

/**
 * @title PlatformSubscription
 * @dev Platform-wide subscription contract for fixed monthly KAS payments
 * @notice Users pay a fixed monthly fee set by Kasparex to access all premium dApps
 */
contract PlatformSubscription is Ownable, ReentrancyGuard {
    // Treasury contract for fee collection
    Treasury public treasury;

    // Fixed monthly subscription price (in wei)
    uint256 public monthlyPrice;

    // Subscription period in seconds (default: 30 days)
    uint256 public subscriptionPeriod;

    // Grace period in seconds (default: 7 days)
    uint256 public gracePeriod;

    // Kasparex fee percentage (basis points, e.g., 1500 = 15%)
    uint256 public kasparexFeePercentage;

    // Subscription info for each user
    struct Subscription {
        uint256 expiryTimestamp; // When subscription expires (0 = never subscribed)
        bool isActive; // Whether subscription is currently active
    }

    // Mapping from user address to subscription
    mapping(address => Subscription) public subscriptions;

    // Events
    event SubscriptionPurchased(
        address indexed user,
        uint256 amount,
        uint256 expiryTimestamp,
        uint256 timestamp
    );
    event SubscriptionRenewed(
        address indexed user,
        uint256 amount,
        uint256 newExpiryTimestamp,
        uint256 timestamp
    );
    event SubscriptionExpired(address indexed user, uint256 timestamp);
    event MonthlyPriceUpdated(uint256 oldPrice, uint256 newPrice);
    event SubscriptionPeriodUpdated(uint256 oldPeriod, uint256 newPeriod);
    event GracePeriodUpdated(uint256 oldPeriod, uint256 newPeriod);
    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);

    /**
     * @dev Constructor sets initial values
     * @param _treasury Address of the Treasury contract
     * @param _monthlyPrice Monthly subscription price in wei
     * @param _subscriptionPeriod Subscription period in seconds (default: 30 days)
     * @param _gracePeriod Grace period in seconds (default: 7 days)
     * @param _kasparexFeePercentage Kasparex fee percentage in basis points (default: 1500 = 15%)
     */
    constructor(
        address _treasury,
        uint256 _monthlyPrice,
        uint256 _subscriptionPeriod,
        uint256 _gracePeriod,
        uint256 _kasparexFeePercentage
    ) Ownable(msg.sender) {
        require(_treasury != address(0), "PlatformSubscription: Invalid treasury address");
        require(_monthlyPrice > 0, "PlatformSubscription: Price must be greater than 0");
        require(_kasparexFeePercentage <= 10000, "PlatformSubscription: Fee cannot exceed 100%");

        treasury = Treasury(_treasury);
        monthlyPrice = _monthlyPrice;
        subscriptionPeriod = _subscriptionPeriod;
        gracePeriod = _gracePeriod;
        kasparexFeePercentage = _kasparexFeePercentage;
    }

    /**
     * @dev Purchase or renew a platform subscription
     * @notice Users pay the fixed monthly price to access all premium dApps
     */
    function subscribe() external payable nonReentrant {
        require(msg.value >= monthlyPrice, "PlatformSubscription: Insufficient payment");

        uint256 kasparexFee = (msg.value * kasparexFeePercentage) / 10000;

        // Send Kasparex fee to treasury
        if (kasparexFee > 0) {
            treasury.collectFee{value: kasparexFee}();
        }

        // Calculate new expiry timestamp
        uint256 currentExpiry = subscriptions[msg.sender].expiryTimestamp;
        uint256 newExpiry;

        if (currentExpiry > block.timestamp) {
            // Renew existing active subscription
            newExpiry = currentExpiry + subscriptionPeriod;
            emit SubscriptionRenewed(msg.sender, msg.value, newExpiry, block.timestamp);
        } else {
            // New subscription
            newExpiry = block.timestamp + subscriptionPeriod;
            emit SubscriptionPurchased(msg.sender, msg.value, newExpiry, block.timestamp);
        }

        subscriptions[msg.sender] = Subscription({
            expiryTimestamp: newExpiry,
            isActive: true
        });

        // Refund excess payment
        if (msg.value > monthlyPrice) {
            uint256 refund = msg.value - monthlyPrice;
            (bool success, ) = payable(msg.sender).call{value: refund}("");
            require(success, "PlatformSubscription: Refund failed");
        }
    }

    /**
     * @dev Check if a user has an active subscription
     * @param _user Address to check
     * @return bool True if subscription is active
     */
    function isSubscribed(address _user) external view returns (bool) {
        Subscription memory sub = subscriptions[_user];
        if (!sub.isActive) return false;
        
        // Check if subscription has expired (including grace period)
        if (sub.expiryTimestamp > 0 && block.timestamp > sub.expiryTimestamp + gracePeriod) {
            return false;
        }
        
        return block.timestamp <= sub.expiryTimestamp;
    }

    /**
     * @dev Check if a user is in grace period
     * @param _user Address to check
     * @return bool True if in grace period
     */
    function isInGracePeriod(address _user) external view returns (bool) {
        Subscription memory sub = subscriptions[_user];
        if (!sub.isActive || sub.expiryTimestamp == 0) return false;
        
        return block.timestamp > sub.expiryTimestamp && 
               block.timestamp <= sub.expiryTimestamp + gracePeriod;
    }

    /**
     * @dev Get subscription expiry timestamp for a user
     * @param _user Address to check
     * @return uint256 Expiry timestamp (0 if not subscribed)
     */
    function getExpiryTimestamp(address _user) external view returns (uint256) {
        return subscriptions[_user].expiryTimestamp;
    }

    /**
     * @dev Update monthly subscription price (only owner)
     * @param _newPrice New monthly price in wei
     */
    function setMonthlyPrice(uint256 _newPrice) external onlyOwner {
        require(_newPrice > 0, "PlatformSubscription: Price must be greater than 0");
        uint256 oldPrice = monthlyPrice;
        monthlyPrice = _newPrice;
        emit MonthlyPriceUpdated(oldPrice, _newPrice);
    }

    /**
     * @dev Update subscription period (only owner)
     * @param _newPeriod New subscription period in seconds
     */
    function setSubscriptionPeriod(uint256 _newPeriod) external onlyOwner {
        require(_newPeriod > 0, "PlatformSubscription: Period must be greater than 0");
        uint256 oldPeriod = subscriptionPeriod;
        subscriptionPeriod = _newPeriod;
        emit SubscriptionPeriodUpdated(oldPeriod, _newPeriod);
    }

    /**
     * @dev Update grace period (only owner)
     * @param _newPeriod New grace period in seconds
     */
    function setGracePeriod(uint256 _newPeriod) external onlyOwner {
        uint256 oldPeriod = gracePeriod;
        gracePeriod = _newPeriod;
        emit GracePeriodUpdated(oldPeriod, _newPeriod);
    }

    /**
     * @dev Update Kasparex fee percentage (only owner)
     * @param _newPercentage New fee percentage in basis points
     */
    function setKasparexFeePercentage(uint256 _newPercentage) external onlyOwner {
        require(_newPercentage <= 10000, "PlatformSubscription: Fee cannot exceed 100%");
        kasparexFeePercentage = _newPercentage;
    }

    /**
     * @dev Update Treasury contract address (only owner)
     * @param _treasury New Treasury contract address
     */
    function setTreasury(address _treasury) external onlyOwner {
        require(_treasury != address(0), "PlatformSubscription: Invalid treasury address");
        address oldTreasury = address(treasury);
        treasury = Treasury(_treasury);
        emit TreasuryUpdated(oldTreasury, _treasury);
    }

    /**
     * @dev Deactivate a subscription (admin function for expired subscriptions)
     * @param _user Address to deactivate
     */
    function deactivateSubscription(address _user) external onlyOwner {
        if (subscriptions[_user].isActive) {
            subscriptions[_user].isActive = false;
            emit SubscriptionExpired(_user, block.timestamp);
        }
    }

    /**
     * @dev Get contract balance
     * @return uint256 Current balance
     */
    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }

    /**
     * @dev Withdraw funds to treasury (only owner)
     * @param _amount Amount to withdraw
     */
    function withdrawToTreasury(uint256 _amount) external onlyOwner nonReentrant {
        require(_amount <= address(this).balance, "PlatformSubscription: Insufficient balance");
        treasury.collectFee{value: _amount}();
    }
}

contracts/ProfileRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title ProfileRegistry
 * @dev On-chain profile storage (IPFS CIDs)
 * @notice Maps wallet address to IPFS CID, minimal on-chain storage
 */
contract ProfileRegistry is Ownable {
    // Profile structure
    struct Profile {
        string ipfsCID; // IPFS CID for profile metadata
        string displayName; // Optional on-chain display name
        bool verified; // Verified status
        bytes preferences; // Encoded preferences
        uint256 updatedAt; // Last update timestamp
    }
    
    // User profiles
    mapping(address => Profile) public profiles;
    
    // Verified addresses (for badge display)
    mapping(address => bool) public verifiedAddresses;
    
    // Events
    event ProfileUpdated(address indexed user, string ipfsCID, uint256 timestamp);
    event DisplayNameUpdated(address indexed user, string displayName, uint256 timestamp);
    event VerificationUpdated(address indexed user, bool verified, uint256 timestamp);
    event PreferencesUpdated(address indexed user, bytes preferences, uint256 timestamp);
    
    /**
     * @dev Constructor
     */
    constructor() Ownable(msg.sender) {}
    
    /**
     * @dev Set profile IPFS CID
     * @param user User address
     * @param ipfsCID IPFS CID for profile metadata
     */
    function setProfileCID(address user, string memory ipfsCID) external {
        require(user != address(0), "ProfileRegistry: Invalid user");
        require(bytes(ipfsCID).length > 0, "ProfileRegistry: Invalid IPFS CID");
        
        // Only user or owner can update
        require(msg.sender == user || msg.sender == owner(), "ProfileRegistry: Not authorized");
        
        profiles[user].ipfsCID = ipfsCID;
        profiles[user].updatedAt = block.timestamp;
        
        emit ProfileUpdated(user, ipfsCID, block.timestamp);
    }
    
    /**
     * @dev Set display name (optional on-chain field)
     * @param user User address
     * @param displayName Display name
     */
    function setDisplayName(address user, string memory displayName) external {
        require(user != address(0), "ProfileRegistry: Invalid user");
        require(msg.sender == user || msg.sender == owner(), "ProfileRegistry: Not authorized");
        
        profiles[user].displayName = displayName;
        emit DisplayNameUpdated(user, displayName, block.timestamp);
    }
    
    /**
     * @dev Set verified status (only owner)
     * @param user User address
     * @param verified Verified status
     */
    function setVerified(address user, bool verified) external onlyOwner {
        require(user != address(0), "ProfileRegistry: Invalid user");
        
        profiles[user].verified = verified;
        verifiedAddresses[user] = verified;
        
        emit VerificationUpdated(user, verified, block.timestamp);
    }
    
    /**
     * @dev Set preferences
     * @param user User address
     * @param preferences Encoded preferences
     */
    function setPreferences(address user, bytes memory preferences) external {
        require(user != address(0), "ProfileRegistry: Invalid user");
        require(msg.sender == user || msg.sender == owner(), "ProfileRegistry: Not authorized");
        
        profiles[user].preferences = preferences;
        emit PreferencesUpdated(user, preferences, block.timestamp);
    }
    
    /**
     * @dev Get profile
     * @param user User address
     * @return Profile struct
     */
    function getProfile(address user) external view returns (Profile memory) {
        return profiles[user];
    }
    
    /**
     * @dev Get profile IPFS CID
     * @param user User address
     * @return IPFS CID
     */
    function getProfileCID(address user) external view returns (string memory) {
        return profiles[user].ipfsCID;
    }
    
    /**
     * @dev Batch update profiles (only owner, gas optimization)
     * @param users Array of user addresses
     * @param ipfsCIDs Array of IPFS CIDs
     */
    function batchUpdateProfiles(address[] memory users, string[] memory ipfsCIDs) external onlyOwner {
        require(users.length == ipfsCIDs.length, "ProfileRegistry: Array length mismatch");
        
        for (uint256 i = 0; i < users.length; i++) {
            if (users[i] != address(0) && bytes(ipfsCIDs[i]).length > 0) {
                profiles[users[i]].ipfsCID = ipfsCIDs[i];
                profiles[users[i]].updatedAt = block.timestamp;
                emit ProfileUpdated(users[i], ipfsCIDs[i], block.timestamp);
            }
        }
    }
}

contracts/PromoMintRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./DAppToken.sol";

/**
 * @title PromoMintRouter
 * @dev Mint router for Kasparex token + promotion engine.
 *
 * Responsibilities:
 * - Hold per-token mint configuration (price, tokens per mint, mintable supply, creator/platform wallets).
 * - Enforce percentage-based revenue sharing across creator, platform, and 5 promo slots.
 * - Enforce basic on-chain security for fairness and bot resistance:
 *   - Per-wallet cooldown between mints.
 *   - Daily mint limits per wallet.
 *   - Maximum mints per transaction.
 *   - Optional lifetime mint cap per wallet.
 *
 * Notes:
 * - Slot addresses are provided by the caller based on off-chain promo page state.
 *   Off-chain (Cloudflare Worker + D1) remains canonical for page ownership and rotation.
 * - This contract focuses on transparent, deterministic revenue sharing and basic rate limiting.
 */
contract PromoMintRouter is Ownable, ReentrancyGuard {
    // -------------------------
    // Token configuration
    // -------------------------

    struct TokenConfig {
        address token;          // DAppToken ERC-20 contract
        uint256 mintPrice;      // Price per mint in native token units
        uint256 tokensPerMint;  // Number of tokens minted per mint
        uint256 mintableSupply; // Total mintable amount tracked by router
        uint256 mintedSoFar;    // Amount minted so far (router-side view)
        address creator;        // Token creator wallet
        address platform;       // Kasparex platform wallet
        bool active;            // Whether minting is active
        // Percentages in basis points (10000 = 100%)
        uint16 creatorBps;
        uint16 platformBps;
        uint16[5] slotBps;      // Slot1..Slot5 basis points
    }

    // tokenId (keccak256 of an external identifier, e.g. ticker or registry ID) -> config
    mapping(bytes32 => TokenConfig) public tokenConfigs;

    // -------------------------
    // On-chain security config
    // -------------------------

    struct WalletSecurity {
        uint64 lastMintDay;     // UTC day index (timestamp / 1 days)
        uint64 mintsToday;      // Mints performed in the current day
        uint64 lastMintTime;    // Last mint timestamp (seconds)
        uint256 totalMints;     // Lifetime mints through this router
    }

    // Per-wallet mint security tracking (across all tokens)
    mapping(address => WalletSecurity) public walletSecurity;

    // Cooldown: minimum seconds between mints per wallet
    uint256 public cooldownSeconds = 60;

    // Maximum mints allowed per wallet per day (across all tokens)
    uint256 public maxMintsPerDay = 10;

    // Maximum mints allowed per transaction
    uint256 public maxMintsPerTx = 5;

    // Optional lifetime mint cap per wallet (0 = disabled / unlimited)
    uint256 public maxMintsPerWallet = 0;

    // -------------------------
    // Events
    // -------------------------

    event TokenRegistered(
        bytes32 indexed tokenId,
        address indexed token,
        uint256 mintPrice,
        uint256 tokensPerMint,
        uint256 mintableSupply,
        address indexed creator,
        address platform
    );

    event TokenPercentagesUpdated(
        bytes32 indexed tokenId,
        uint16 creatorBps,
        uint16 platformBps,
        uint16[5] slotBps
    );

    event SecurityParamsUpdated(
        uint256 cooldownSeconds,
        uint256 maxMintsPerDay,
        uint256 maxMintsPerTx,
        uint256 maxMintsPerWallet
    );

    event MintExecuted(
        bytes32 indexed tokenId,
        bytes32 indexed pageId,
        address indexed minter,
        uint256 mintCount,
        uint256 mintPrice,
        uint256 totalPaid,
        address creator,
        address platform,
        address[5] slotsBefore,
        uint256 creatorAmount,
        uint256 platformAmount,
        uint256[5] slotAmounts,
        uint256 timestamp
    );

    event MintBlocked(
        address indexed wallet,
        bytes32 indexed tokenId,
        string reason
    );

    // -------------------------
    // Constructor
    // -------------------------

    constructor(address initialOwner) Ownable(initialOwner) {}

    // -------------------------
    // Admin functions
    // -------------------------

    /**
     * @dev Register a new token configuration.
     * @param tokenId External identifier for this token (e.g. keccak256 of ticker or registry ID).
     * @param token Address of the DAppToken contract.
     * @param mintPrice Mint price in native token units.
     * @param tokensPerMint Amount of tokens minted per mint.
     * @param mintableSupply Total mintable amount tracked by the router.
     * @param creator Creator wallet address.
     * @param platform Platform wallet address.
     * @param creatorBps Creator percentage in basis points.
     * @param platformBps Platform percentage in basis points.
     * @param slotBps Slot percentages (5 entries) in basis points.
     */
    function registerToken(
        bytes32 tokenId,
        address token,
        uint256 mintPrice,
        uint256 tokensPerMint,
        uint256 mintableSupply,
        address creator,
        address platform,
        uint16 creatorBps,
        uint16 platformBps,
        uint16[5] calldata slotBps
    ) external onlyOwner {
        require(tokenId != bytes32(0), "PromoMintRouter: invalid tokenId");
        require(token != address(0), "PromoMintRouter: invalid token");
        require(mintPrice > 0, "PromoMintRouter: mint price must be > 0");
        require(tokensPerMint > 0, "PromoMintRouter: tokensPerMint must be > 0");
        require(mintableSupply > 0, "PromoMintRouter: mintableSupply must be > 0");
        require(creator != address(0), "PromoMintRouter: invalid creator");
        require(platform != address(0), "PromoMintRouter: invalid platform");

        // Ensure percentages sum to 100%
        uint256 totalBps = uint256(creatorBps) + uint256(platformBps);
        for (uint256 i = 0; i < 5; i++) {
            totalBps += uint256(slotBps[i]);
        }
        require(totalBps == 10000, "PromoMintRouter: percentages must sum to 10000");

        TokenConfig storage cfg = tokenConfigs[tokenId];
        require(cfg.token == address(0), "PromoMintRouter: token already registered");

        cfg.token = token;
        cfg.mintPrice = mintPrice;
        cfg.tokensPerMint = tokensPerMint;
        cfg.mintableSupply = mintableSupply;
        cfg.mintedSoFar = 0;
        cfg.creator = creator;
        cfg.platform = platform;
        cfg.active = true;
        cfg.creatorBps = creatorBps;
        cfg.platformBps = platformBps;
        cfg.slotBps = slotBps;

        emit TokenRegistered(
            tokenId,
            token,
            mintPrice,
            tokensPerMint,
            mintableSupply,
            creator,
            platform
        );

        emit TokenPercentagesUpdated(tokenId, creatorBps, platformBps, slotBps);
    }

    /**
     * @dev Update percentages for an existing token.
     */
    function setPercentages(
        bytes32 tokenId,
        uint16 creatorBps,
        uint16 platformBps,
        uint16[5] calldata slotBps
    ) external onlyOwner {
        TokenConfig storage cfg = tokenConfigs[tokenId];
        require(cfg.token != address(0), "PromoMintRouter: unknown token");

        uint256 totalBps = uint256(creatorBps) + uint256(platformBps);
        for (uint256 i = 0; i < 5; i++) {
            totalBps += uint256(slotBps[i]);
        }
        require(totalBps == 10000, "PromoMintRouter: percentages must sum to 10000");

        cfg.creatorBps = creatorBps;
        cfg.platformBps = platformBps;
        cfg.slotBps = slotBps;

        emit TokenPercentagesUpdated(tokenId, creatorBps, platformBps, slotBps);
    }

    /**
     * @dev Set active status for a token.
     */
    function setActive(bytes32 tokenId, bool active) external onlyOwner {
        TokenConfig storage cfg = tokenConfigs[tokenId];
        require(cfg.token != address(0), "PromoMintRouter: unknown token");
        cfg.active = active;
    }

    /**
     * @dev Mark a token as completed, disabling further minting.
     */
    function completeMinting(bytes32 tokenId) external onlyOwner {
        TokenConfig storage cfg = tokenConfigs[tokenId];
        require(cfg.token != address(0), "PromoMintRouter: unknown token");
        cfg.active = false;
    }

    /**
     * @dev Configure global security parameters.
     */
    function setSecurityParams(
        uint256 _cooldownSeconds,
        uint256 _maxMintsPerDay,
        uint256 _maxMintsPerTx,
        uint256 _maxMintsPerWallet
    ) external onlyOwner {
        require(_maxMintsPerTx > 0, "PromoMintRouter: maxMintsPerTx must be > 0");
        cooldownSeconds = _cooldownSeconds;
        maxMintsPerDay = _maxMintsPerDay;
        maxMintsPerTx = _maxMintsPerTx;
        maxMintsPerWallet = _maxMintsPerWallet;

        emit SecurityParamsUpdated(
            _cooldownSeconds,
            _maxMintsPerDay,
            _maxMintsPerTx,
            _maxMintsPerWallet
        );
    }

    /**
     * @dev Admin helper to reset a wallet's daily mint count (e.g. manual intervention).
     */
    function resetDailyMintCount(address wallet) external onlyOwner {
        WalletSecurity storage ws = walletSecurity[wallet];
        ws.mintsToday = 0;
    }

    // -------------------------
    // Public view helpers
    // -------------------------

    function getTokenConfig(bytes32 tokenId) external view returns (TokenConfig memory) {
        return tokenConfigs[tokenId];
    }

    function getWalletSecurity(address wallet) external view returns (WalletSecurity memory) {
        return walletSecurity[wallet];
    }

    // -------------------------
    // Internal helpers
    // -------------------------

    function _currentDay() internal view returns (uint64) {
        return uint64(block.timestamp / 1 days);
    }

    function _updateWalletDailyLimits(address wallet, uint256 count) internal returns (bool, string memory) {
        WalletSecurity storage ws = walletSecurity[wallet];
        uint64 today = _currentDay();

        if (ws.lastMintDay != today) {
            ws.lastMintDay = today;
            ws.mintsToday = 0;
        }

        // Cooldown check
        if (cooldownSeconds > 0 && ws.lastMintTime != 0) {
            if (block.timestamp < ws.lastMintTime + cooldownSeconds) {
                return (false, "cooldown active");
            }
        }

        // Daily limit check
        if (maxMintsPerDay > 0) {
            if (uint256(ws.mintsToday) + count > maxMintsPerDay) {
                return (false, "daily mint limit exceeded");
            }
        }

        // Lifetime limit check
        if (maxMintsPerWallet > 0) {
            if (ws.totalMints + count > maxMintsPerWallet) {
                return (false, "lifetime mint limit exceeded");
            }
        }

        // All checks passed, update counters
        ws.mintsToday += uint64(count);
        ws.totalMints += count;
        ws.lastMintTime = uint64(block.timestamp);

        return (true, "");
    }

    // -------------------------
    // Mint function
    // -------------------------

    /**
     * @dev Mint tokens for a specific tokenId via a promo page.
     *
     * @param tokenId Identifier for the token configuration.
     * @param pageId Identifier for the promo page (off-chain context).
     * @param count Number of mints to perform in this transaction.
     * @param pageSlots Slot wallets (slot1..slot5) at the moment of mint.
     */
    function mint(
        bytes32 tokenId,
        bytes32 pageId,
        uint256 count,
        address[5] calldata pageSlots
    ) external payable nonReentrant {
        TokenConfig storage cfg = tokenConfigs[tokenId];
        if (cfg.token == address(0)) {
            emit MintBlocked(msg.sender, tokenId, "unknown token");
            revert("PromoMintRouter: unknown token");
        }
        if (!cfg.active) {
            emit MintBlocked(msg.sender, tokenId, "token inactive");
            revert("PromoMintRouter: minting is not active for this token");
        }

        require(count > 0, "PromoMintRouter: count must be > 0");
        require(count <= maxMintsPerTx, "PromoMintRouter: exceeds maxMintsPerTx");

        // Basic slot validation (no zero addresses)
        for (uint256 i = 0; i < 5; i++) {
            require(pageSlots[i] != address(0), "PromoMintRouter: invalid slot wallet");
        }

        uint256 totalTokensToMint = cfg.tokensPerMint * count;
        require(
            cfg.mintedSoFar + totalTokensToMint <= cfg.mintableSupply,
            "PromoMintRouter: exceeds mintable supply"
        );

        uint256 expectedValue = cfg.mintPrice * count;
        require(msg.value == expectedValue, "PromoMintRouter: incorrect payment amount");

        // On-chain wallet-level security checks
        (bool ok, string memory reason) = _updateWalletDailyLimits(msg.sender, count);
        if (!ok) {
            emit MintBlocked(msg.sender, tokenId, reason);
            revert(reason);
        }

        // Compute payouts
        uint256 totalPaid = msg.value;
        uint256 remaining = totalPaid;

        uint256 creatorAmount = (totalPaid * cfg.creatorBps) / 10000;
        uint256 platformAmount = (totalPaid * cfg.platformBps) / 10000;
        uint256[5] memory slotAmounts;

        for (uint256 i = 0; i < 5; i++) {
            slotAmounts[i] = (totalPaid * cfg.slotBps[i]) / 10000;
        }

        // Adjust remaining to avoid dust
        remaining -= creatorAmount;
        remaining -= platformAmount;
        for (uint256 i = 0; i < 5; i++) {
            remaining -= slotAmounts[i];
        }

        // Send payouts
        // Creator
        if (creatorAmount > 0) {
            (bool cs, ) = payable(cfg.creator).call{value: creatorAmount}("");
            require(cs, "PromoMintRouter: creator payout failed");
        }

        // Platform (includes any rounding dust)
        uint256 platformTotal = platformAmount + remaining;
        if (platformTotal > 0) {
            (bool ps, ) = payable(cfg.platform).call{value: platformTotal}("");
            require(ps, "PromoMintRouter: platform payout failed");
        }

        // Slots
        for (uint256 i = 0; i < 5; i++) {
            uint256 amount = slotAmounts[i];
            if (amount > 0) {
                (bool ss, ) = payable(pageSlots[i]).call{value: amount}("");
                require(ss, "PromoMintRouter: slot payout failed");
            }
        }

        // Mint tokens to user
        DAppToken(cfg.token).mint(msg.sender, totalTokensToMint);

        // Update supply tracking
        cfg.mintedSoFar += totalTokensToMint;
        if (cfg.mintedSoFar >= cfg.mintableSupply) {
            cfg.active = false;
        }

        emit MintExecuted(
            tokenId,
            pageId,
            msg.sender,
            count,
            cfg.mintPrice,
            totalPaid,
            cfg.creator,
            cfg.platform,
            pageSlots,
            creatorAmount,
            platformAmount,
            slotAmounts,
            block.timestamp
        );
    }
}

contracts/ProofOfUtility.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./DAppToken.sol";
import "./GRIDToken.sol";
import "./RewardManager.sol";

/**
 * @title ProofOfUtility
 * @dev Tracks on-chain usage events and mints rewards
 * @notice Gas-efficient P-o-U tracking with batch processing
 */
contract ProofOfUtility is Ownable, ReentrancyGuard {
    // RewardManager contract
    RewardManager public rewardManager;
    
    // Usage event structure
    struct UsageEvent {
        address user;
        address dAppContract;
        uint256 dAppId;
        string actionType; // e.g., "vote", "proposal", "payment"
        uint256 timestamp;
    }
    
    // Track events per user
    mapping(address => UsageEvent[]) public userEvents;
    
    // Track events per dApp
    mapping(address => UsageEvent[]) public dAppEvents;
    
    // Event counter
    uint256 public totalEvents;
    
    // Events
    event UsageEventRecorded(
        address indexed user,
        address indexed dAppContract,
        uint256 indexed dAppId,
        string actionType,
        uint256 timestamp
    );
    event RewardMinted(
        address indexed user,
        address indexed token,
        uint256 amount,
        string rewardType
    );
    event RewardManagerUpdated(address indexed oldManager, address indexed newManager);
    
    /**
     * @dev Constructor
     * @param _rewardManager Address of RewardManager contract
     */
    constructor(address _rewardManager) Ownable(msg.sender) {
        require(_rewardManager != address(0), "ProofOfUtility: Invalid reward manager");
        rewardManager = RewardManager(_rewardManager);
    }
    
    /**
     * @dev Record a usage event (called by dApp contracts)
     * @param user Address of the user
     * @param dAppContract Address of the dApp contract
     * @param dAppId ID of the dApp
     * @param actionType Type of action performed
     */
    function recordUsage(
        address user,
        address dAppContract,
        uint256 dAppId,
        string memory actionType
    ) public {
        require(user != address(0), "ProofOfUtility: Invalid user");
        require(dAppContract != address(0), "ProofOfUtility: Invalid dApp contract");
        
        UsageEvent memory event_ = UsageEvent({
            user: user,
            dAppContract: dAppContract,
            dAppId: dAppId,
            actionType: actionType,
            timestamp: block.timestamp
        });
        
        userEvents[user].push(event_);
        dAppEvents[dAppContract].push(event_);
        totalEvents++;
        
        emit UsageEventRecorded(user, dAppContract, dAppId, actionType, block.timestamp);
    }
    
    /**
     * @dev Record multiple usage events in batch (gas optimization)
     * @param users Array of user addresses
     * @param dAppContracts Array of dApp contract addresses
     * @param dAppIds Array of dApp IDs
     * @param actionTypes Array of action types
     */
    function recordUsageBatch(
        address[] memory users,
        address[] memory dAppContracts,
        uint256[] memory dAppIds,
        string[] memory actionTypes
    ) external {
        require(
            users.length == dAppContracts.length &&
            dAppContracts.length == dAppIds.length &&
            dAppIds.length == actionTypes.length,
            "ProofOfUtility: Array length mismatch"
        );
        
        for (uint256 i = 0; i < users.length; i++) {
            // Inline recordUsage logic for gas efficiency
            address user = users[i];
            address dAppContract = dAppContracts[i];
            uint256 dAppId = dAppIds[i];
            string memory actionType = actionTypes[i];
            
            require(user != address(0), "ProofOfUtility: Invalid user");
            require(dAppContract != address(0), "ProofOfUtility: Invalid dApp contract");
            
            UsageEvent memory event_ = UsageEvent({
                user: user,
                dAppContract: dAppContract,
                dAppId: dAppId,
                actionType: actionType,
                timestamp: block.timestamp
            });
            
            userEvents[user].push(event_);
            dAppEvents[dAppContract].push(event_);
            totalEvents++;
            
            emit UsageEventRecorded(user, dAppContract, dAppId, actionType, block.timestamp);
        }
    }
    
    /**
     * @dev Get user's usage events
     * @param user User address
     * @return Array of usage events
     */
    function getUserEvents(address user) external view returns (UsageEvent[] memory) {
        return userEvents[user];
    }
    
    /**
     * @dev Get dApp's usage events
     * @param dAppContract dApp contract address
     * @return Array of usage events
     */
    function getDAppEvents(address dAppContract) external view returns (UsageEvent[] memory) {
        return dAppEvents[dAppContract];
    }
    
    /**
     * @dev Get user's event count
     * @param user User address
     * @return Event count
     */
    function getUserEventCount(address user) external view returns (uint256) {
        return userEvents[user].length;
    }
    
    /**
     * @dev Record usage and distribute reward (called by dApp contracts)
     * @param user Address of the user
     * @param dAppContract Address of the dApp contract
     * @param dAppId ID of the dApp
     * @param actionType Type of action performed
     * @param actionValue Value of the action (for reward calculation)
     */
    function recordUsageAndReward(
        address user,
        address dAppContract,
        uint256 dAppId,
        string memory actionType,
        uint256 actionValue
    ) public {
        require(user != address(0), "ProofOfUtility: Invalid user");
        require(dAppContract != address(0), "ProofOfUtility: Invalid dApp contract");
        
        // Record usage event
        UsageEvent memory event_ = UsageEvent({
            user: user,
            dAppContract: dAppContract,
            dAppId: dAppId,
            actionType: actionType,
            timestamp: block.timestamp
        });
        
        userEvents[user].push(event_);
        dAppEvents[dAppContract].push(event_);
        totalEvents++;
        
        emit UsageEventRecorded(user, dAppContract, dAppId, actionType, block.timestamp);
        
        // Distribute reward if actionValue > 0
        if (actionValue > 0) {
            rewardManager.distributeReward(user, dAppContract, actionValue);
        }
    }
    
    /**
     * @dev Update reward manager (only owner)
     * @param _rewardManager New reward manager address
     */
    function setRewardManager(address _rewardManager) external onlyOwner {
        require(_rewardManager != address(0), "ProofOfUtility: Invalid reward manager");
        address oldManager = address(rewardManager);
        rewardManager = RewardManager(_rewardManager);
        emit RewardManagerUpdated(oldManager, _rewardManager);
    }
}

contracts/QuizToEarn.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./FeeCollector.sol";
import "./ProofOfUtility.sol";

/**
 * @title QuizToEarn
 * @dev Quiz game where users answer questions to earn rewards
 * @notice Users answer crypto/ecosystem questions and earn GRID or token rewards for correct answers
 */
contract QuizToEarn is Ownable, ReentrancyGuard {
    FeeCollector public feeCollector;
    ProofOfUtility public proofOfUtility;
    uint256 public dAppId; // To be set by DAppRegistry after registration
    
    // Default fee configuration (1% = 100 basis points)
    uint256 public feePercentage = 100; // 1% default fee
    uint256 public constant BASIS_POINTS = 10000; // 100% = 10000 basis points
    
    // Quiz question structure
    struct Question {
        uint256 id;
        string questionText;
        string[] options; // Array of answer options
        uint256 correctAnswerIndex; // Index of correct answer (0-based)
        string category; // e.g., "Kaspa", "BlockDAG", "General"
        uint256 rewardAmount; // Reward amount in wei for correct answer
        bool isActive; // Whether question is active
        uint256 createdAt;
    }
    
    // User answer tracking
    struct UserAnswer {
        uint256 questionId;
        uint256 selectedAnswerIndex;
        bool isCorrect;
        uint256 timestamp;
        bool rewardClaimed;
    }
    
    // State variables
    mapping(uint256 => Question) public questions;
    mapping(address => mapping(uint256 => UserAnswer)) public userAnswers; // user => questionId => answer
    mapping(address => uint256[]) public userAnsweredQuestions; // user => array of question IDs
    uint256 public questionCount;
    uint256 public defaultRewardAmount; // Default reward value per correct answer (used for RewardManager calculation, represents token value, not KAS)
    
    // Events
    event QuestionAdded(
        uint256 indexed questionId,
        string questionText,
        string category,
        uint256 rewardAmount,
        uint256 timestamp
    );
    event QuestionUpdated(uint256 indexed questionId, bool isActive);
    event AnswerSubmitted(
        address indexed user,
        uint256 indexed questionId,
        uint256 selectedAnswerIndex,
        bool isCorrect,
        uint256 rewardAmount,
        uint256 timestamp
    );
    event RewardClaimed(
        address indexed user,
        uint256 indexed questionId,
        uint256 rewardAmount,
        uint256 timestamp
    );
    event DAppInitialized(uint256 indexed dAppId, address indexed deployer, uint256 timestamp);
    event DefaultRewardUpdated(uint256 oldReward, uint256 newReward);
    
    /**
     * @dev Constructor
     * @param _feeCollector Address of the FeeCollector contract
     * @param _proofOfUtility Address of the ProofOfUtility contract
     * @param _feePercentage Initial fee percentage in basis points (default: 100 = 1%)
     * @param _defaultRewardAmount Default reward value per correct answer (used for RewardManager calculation, represents token value, not KAS)
     */
    constructor(
        address _feeCollector,
        address _proofOfUtility,
        uint256 _feePercentage,
        uint256 _defaultRewardAmount
    ) Ownable(msg.sender) {
        require(_feeCollector != address(0), "QuizToEarn: Invalid fee collector");
        require(_proofOfUtility != address(0), "QuizToEarn: Invalid ProofOfUtility");
        require(_feePercentage <= BASIS_POINTS, "QuizToEarn: Fee percentage too high");
        
        feeCollector = FeeCollector(_feeCollector);
        proofOfUtility = ProofOfUtility(_proofOfUtility);
        feePercentage = _feePercentage == 0 ? 100 : _feePercentage; // Default to 1% if not provided
        defaultRewardAmount = _defaultRewardAmount;
    }
    
    /**
     * @dev Sets the dApp ID after registration in the DAppRegistry.
     *      This function can only be called once by the owner.
     * @param _dAppId The ID assigned by the DAppRegistry.
     */
    function setDAppId(uint256 _dAppId) external onlyOwner {
        require(dAppId == 0, "QuizToEarn: dApp ID already set");
        require(_dAppId > 0, "QuizToEarn: Invalid dApp ID");
        dAppId = _dAppId;
        emit DAppInitialized(dAppId, msg.sender, block.timestamp);
    }
    
    /**
     * @dev Add a new quiz question (admin only)
     * @param _questionText The question text
     * @param _options Array of answer options
     * @param _correctAnswerIndex Index of the correct answer (0-based)
     * @param _category Category of the question (e.g., "Kaspa", "BlockDAG")
     * @param _rewardAmount Reward value for correct answer (used for RewardManager calculation, represents token value, not KAS. 0 = use default)
     */
    function addQuestion(
        string memory _questionText,
        string[] memory _options,
        uint256 _correctAnswerIndex,
        string memory _category,
        uint256 _rewardAmount
    ) external onlyOwner {
        require(bytes(_questionText).length > 0, "QuizToEarn: Question text cannot be empty");
        require(_options.length >= 2, "QuizToEarn: Must have at least 2 options");
        require(_correctAnswerIndex < _options.length, "QuizToEarn: Invalid correct answer index");
        
        questionCount++;
        uint256 rewardAmount = _rewardAmount == 0 ? defaultRewardAmount : _rewardAmount;
        
        questions[questionCount] = Question({
            id: questionCount,
            questionText: _questionText,
            options: _options,
            correctAnswerIndex: _correctAnswerIndex,
            category: _category,
            rewardAmount: rewardAmount,
            isActive: true,
            createdAt: block.timestamp
        });
        
        emit QuestionAdded(questionCount, _questionText, _category, rewardAmount, block.timestamp);
    }
    
    /**
     * @dev Update question active status (admin only)
     * @param _questionId Question ID
     * @param _isActive Whether question is active
     */
    function updateQuestionStatus(uint256 _questionId, bool _isActive) external onlyOwner {
        require(_questionId > 0 && _questionId <= questionCount, "QuizToEarn: Invalid question ID");
        questions[_questionId].isActive = _isActive;
        emit QuestionUpdated(_questionId, _isActive);
    }
    
    /**
     * @dev Submit an answer to a question
     * @param _questionId Question ID
     * @param _selectedAnswerIndex Selected answer index (0-based)
     */
    function submitAnswer(uint256 _questionId, uint256 _selectedAnswerIndex) external nonReentrant {
        require(_questionId > 0 && _questionId <= questionCount, "QuizToEarn: Invalid question ID");
        Question storage question = questions[_questionId];
        require(question.isActive, "QuizToEarn: Question is not active");
        require(_selectedAnswerIndex < question.options.length, "QuizToEarn: Invalid answer index");
        require(
            userAnswers[msg.sender][_questionId].timestamp == 0,
            "QuizToEarn: Question already answered"
        );
        
        bool isCorrect = _selectedAnswerIndex == question.correctAnswerIndex;
        
        userAnswers[msg.sender][_questionId] = UserAnswer({
            questionId: _questionId,
            selectedAnswerIndex: _selectedAnswerIndex,
            isCorrect: isCorrect,
            timestamp: block.timestamp,
            rewardClaimed: false
        });
        
        userAnsweredQuestions[msg.sender].push(_questionId);
        
        // Record usage event and distribute reward via ProofOfUtility
        // Only distribute rewards for correct answers
        if (dAppId > 0 && isCorrect) {
            // Use rewardAmount as actionValue (represents value in token terms, not KAS)
            // RewardManager will calculate actual token reward: actionValue × rewardRate
            proofOfUtility.recordUsageAndReward(
                msg.sender,
                address(this),
                dAppId,
                "quiz_correct_answer",
                question.rewardAmount // This represents the value, RewardManager calculates token amount
            );
        } else if (dAppId > 0) {
            // Record wrong answer without reward
            proofOfUtility.recordUsage(
                msg.sender,
                address(this),
                dAppId,
                "quiz_wrong_answer"
            );
        }
        
        emit AnswerSubmitted(
            msg.sender,
            _questionId,
            _selectedAnswerIndex,
            isCorrect,
            isCorrect ? question.rewardAmount : 0,
            block.timestamp
        );
    }
    
    /**
     * @dev Get a question by ID
     * @param _questionId Question ID
     * @return id Question ID
     * @return questionText Question text
     * @return options Array of answer options
     * @return category Question category
     * @return rewardAmount Reward amount for correct answer
     * @return isActive Whether question is active
     * @return createdAt Creation timestamp
     */
    function getQuestion(uint256 _questionId) external view returns (
        uint256 id,
        string memory questionText,
        string[] memory options,
        string memory category,
        uint256 rewardAmount,
        bool isActive,
        uint256 createdAt
    ) {
        require(_questionId > 0 && _questionId <= questionCount, "QuizToEarn: Invalid question ID");
        Question storage q = questions[_questionId];
        return (
            q.id,
            q.questionText,
            q.options,
            q.category,
            q.rewardAmount,
            q.isActive,
            q.createdAt
        );
    }
    
    /**
     * @dev Get user's answer for a question
     * @param _user User address
     * @param _questionId Question ID
     * @return UserAnswer struct
     */
    function getUserAnswer(address _user, uint256 _questionId) external view returns (UserAnswer memory) {
        return userAnswers[_user][_questionId];
    }
    
    /**
     * @dev Get all question IDs answered by a user
     * @param _user User address
     * @return Array of question IDs
     */
    function getUserAnsweredQuestions(address _user) external view returns (uint256[] memory) {
        return userAnsweredQuestions[_user];
    }
    
    /**
     * @dev Get paginated active questions
     * @param _offset Starting index
     * @param _limit Number of questions to return
     * @return ids Array of question IDs
     * @return questionTexts Array of question texts
     * @return optionsArray Array of options arrays
     * @return categories Array of categories
     * @return rewardAmounts Array of reward amounts
     */
    function getActiveQuestions(uint256 _offset, uint256 _limit) external view returns (
        uint256[] memory ids,
        string[] memory questionTexts,
        string[][] memory optionsArray,
        string[] memory categories,
        uint256[] memory rewardAmounts
    ) {
        require(_limit > 0 && _limit <= 50, "QuizToEarn: Invalid limit");
        
        uint256 count = 0;
        uint256[] memory tempIds = new uint256[](_limit);
        string[] memory tempTexts = new string[](_limit);
        string[][] memory tempOptions = new string[][](_limit);
        string[] memory tempCategories = new string[](_limit);
        uint256[] memory tempRewards = new uint256[](_limit);
        
        for (uint256 i = _offset + 1; i <= questionCount && count < _limit; i++) {
            if (questions[i].isActive) {
                tempIds[count] = questions[i].id;
                tempTexts[count] = questions[i].questionText;
                tempOptions[count] = questions[i].options;
                tempCategories[count] = questions[i].category;
                tempRewards[count] = questions[i].rewardAmount;
                count++;
            }
        }
        
        // Resize arrays to actual count
        uint256[] memory finalIds = new uint256[](count);
        string[] memory finalTexts = new string[](count);
        string[][] memory finalOptions = new string[][](count);
        string[] memory finalCategories = new string[](count);
        uint256[] memory finalRewards = new uint256[](count);
        
        for (uint256 i = 0; i < count; i++) {
            finalIds[i] = tempIds[i];
            finalTexts[i] = tempTexts[i];
            finalOptions[i] = tempOptions[i];
            finalCategories[i] = tempCategories[i];
            finalRewards[i] = tempRewards[i];
        }
        
        return (finalIds, finalTexts, finalOptions, finalCategories, finalRewards);
    }
    
    /**
     * @dev Update default reward amount (admin only)
     * @param _newRewardAmount New default reward value (used for RewardManager calculation, represents token value, not KAS)
     */
    function setDefaultRewardAmount(uint256 _newRewardAmount) external onlyOwner {
        uint256 oldReward = defaultRewardAmount;
        defaultRewardAmount = _newRewardAmount;
        emit DefaultRewardUpdated(oldReward, _newRewardAmount);
    }
    
    /**
     * @dev Admin function - Update fee percentage (admin only)
     * @param _newFeePercentage New fee percentage in basis points (e.g., 100 = 1%)
     */
    function setFeePercentage(uint256 _newFeePercentage) external onlyOwner {
        require(_newFeePercentage <= BASIS_POINTS, "QuizToEarn: Fee percentage too high");
        feePercentage = _newFeePercentage;
    }
    
    /**
     * @dev Calculate fee for a given amount
     * @param _amount Amount to calculate fee for
     * @return Fee amount in wei
     */
    function calculateFee(uint256 _amount) public view returns (uint256) {
        return (_amount * feePercentage) / BASIS_POINTS;
    }
    
    /**
     * @dev Admin function - Update fee collector (admin only)
     * @param _feeCollector New fee collector address
     */
    function setFeeCollector(address _feeCollector) external onlyOwner {
        require(_feeCollector != address(0), "QuizToEarn: Invalid fee collector");
        feeCollector = FeeCollector(_feeCollector);
    }
    
    /**
     * @dev Admin function - Update ProofOfUtility (admin only)
     * @param _proofOfUtility New ProofOfUtility address
     */
    function setProofOfUtility(address _proofOfUtility) external onlyOwner {
        require(_proofOfUtility != address(0), "QuizToEarn: Invalid ProofOfUtility");
        proofOfUtility = ProofOfUtility(_proofOfUtility);
    }
}

contracts/RewardManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./DAppToken.sol";
import "./GRIDToken.sol";
import "./ProofOfUtility.sol";

/**
 * @title RewardManager
 * @dev Distributes GRID or dApp tokens based on Proof-of-Utility
 * @notice Mints rewards based on usage events
 */
contract RewardManager is Ownable, ReentrancyGuard {
    // ProofOfUtility contract
    ProofOfUtility public proofOfUtility;
    
    // GRID token
    GRIDToken public gridToken;
    
    // Reward rates per dApp (basis points, e.g., 100 = 1% of action value)
    mapping(address => uint256) public rewardRates; // dApp contract -> reward rate
    
    // Reward type per dApp (GRID or dApp token)
    mapping(address => bool) public useGRID; // true = GRID, false = dApp token
    
    // dApp token contracts
    mapping(address => DAppToken) public dAppTokens; // dApp contract -> token contract
    
    // Events
    event RewardDistributed(
        address indexed user,
        address indexed dAppContract,
        address indexed token,
        uint256 amount,
        string rewardType
    );
    event RewardRateUpdated(address indexed dAppContract, uint256 oldRate, uint256 newRate);
    event RewardTypeUpdated(address indexed dAppContract, bool useGRID);
    event DAppTokenUpdated(address indexed dAppContract, address indexed tokenContract);
    
    /**
     * @dev Constructor
     * @param _proofOfUtility ProofOfUtility contract address
     * @param _gridToken GRID token address
     */
    constructor(address _proofOfUtility, address _gridToken) Ownable(msg.sender) {
        require(_proofOfUtility != address(0), "RewardManager: Invalid ProofOfUtility");
        require(_gridToken != address(0), "RewardManager: Invalid GRID token");
        
        proofOfUtility = ProofOfUtility(_proofOfUtility);
        gridToken = GRIDToken(_gridToken);
    }
    
    /**
     * @dev Distribute reward for a usage event
     * @param user User address
     * @param dAppContract dApp contract address
     * @param actionValue Value of the action (for calculating reward)
     */
    function distributeReward(
        address user,
        address dAppContract,
        uint256 actionValue
    ) public nonReentrant {
        require(user != address(0), "RewardManager: Invalid user");
        require(dAppContract != address(0), "RewardManager: Invalid dApp contract");
        require(msg.sender == address(proofOfUtility), "RewardManager: Only ProofOfUtility can call");
        
        uint256 rewardRate = rewardRates[dAppContract];
        if (rewardRate == 0) {
            return; // No reward configured
        }
        
        uint256 rewardAmount = (actionValue * rewardRate) / 10000;
        if (rewardAmount == 0) {
            return; // No reward to distribute
        }
        
        bool useGRID_ = useGRID[dAppContract];
        
        if (useGRID_) {
            // Distribute GRID token
            require(gridToken.balanceOf(address(this)) >= rewardAmount, "RewardManager: Insufficient GRID");
            require(gridToken.transfer(user, rewardAmount), "RewardManager: GRID transfer failed");
            
            emit RewardDistributed(user, dAppContract, address(gridToken), rewardAmount, "GRID");
        } else {
            // Distribute dApp token
            DAppToken dAppToken = dAppTokens[dAppContract];
            require(address(dAppToken) != address(0), "RewardManager: dApp token not set");
            
            // Mint tokens to user
            dAppToken.mint(user, rewardAmount);
            
            emit RewardDistributed(user, dAppContract, address(dAppToken), rewardAmount, "DAppToken");
        }
    }
    
    /**
     * @dev Batch distribute rewards (gas optimization)
     * @param users Array of user addresses
     * @param dAppContracts Array of dApp contract addresses
     * @param actionValues Array of action values
     */
    function distributeRewardsBatch(
        address[] memory users,
        address[] memory dAppContracts,
        uint256[] memory actionValues
    ) external nonReentrant {
        require(
            users.length == dAppContracts.length &&
            dAppContracts.length == actionValues.length,
            "RewardManager: Array length mismatch"
        );
        require(msg.sender == address(proofOfUtility), "RewardManager: Only ProofOfUtility can call");
        
        for (uint256 i = 0; i < users.length; i++) {
            // Inline distributeReward logic for gas efficiency
            address user = users[i];
            address dAppContract = dAppContracts[i];
            uint256 actionValue = actionValues[i];
            
            require(user != address(0), "RewardManager: Invalid user");
            require(dAppContract != address(0), "RewardManager: Invalid dApp contract");
            
            uint256 rewardRate = rewardRates[dAppContract];
            if (rewardRate == 0) {
                continue; // No reward configured
            }
            
            uint256 rewardAmount = (actionValue * rewardRate) / 10000;
            if (rewardAmount == 0) {
                continue; // No reward to distribute
            }
            
            bool useGRID_ = useGRID[dAppContract];
            
            if (useGRID_) {
                // Distribute GRID token
                require(gridToken.balanceOf(address(this)) >= rewardAmount, "RewardManager: Insufficient GRID");
                require(gridToken.transfer(user, rewardAmount), "RewardManager: GRID transfer failed");
                
                emit RewardDistributed(user, dAppContract, address(gridToken), rewardAmount, "GRID");
            } else {
                // Distribute dApp token
                DAppToken dAppToken = dAppTokens[dAppContract];
                require(address(dAppToken) != address(0), "RewardManager: dApp token not set");
                
                // Mint tokens to user
                dAppToken.mint(user, rewardAmount);
                
                emit RewardDistributed(user, dAppContract, address(dAppToken), rewardAmount, "DAppToken");
            }
        }
    }
    
    /**
     * @dev Set reward rate for a dApp (only owner)
     * @param dAppContract dApp contract address
     * @param rate Reward rate in basis points
     */
    function setRewardRate(address dAppContract, uint256 rate) external onlyOwner {
        require(dAppContract != address(0), "RewardManager: Invalid dApp contract");
        require(rate <= 10000, "RewardManager: Rate cannot exceed 100%");
        
        uint256 oldRate = rewardRates[dAppContract];
        rewardRates[dAppContract] = rate;
        
        emit RewardRateUpdated(dAppContract, oldRate, rate);
    }
    
    /**
     * @dev Set reward type for a dApp (only owner)
     * @param dAppContract dApp contract address
     * @param useGRID_ Whether to use GRID (true) or dApp token (false)
     */
    function setRewardType(address dAppContract, bool useGRID_) external onlyOwner {
        require(dAppContract != address(0), "RewardManager: Invalid dApp contract");
        
        useGRID[dAppContract] = useGRID_;
        emit RewardTypeUpdated(dAppContract, useGRID_);
    }
    
    /**
     * @dev Set dApp token contract (only owner)
     * @param dAppContract dApp contract address
     * @param tokenContract dApp token contract address
     */
    function setDAppToken(address dAppContract, address tokenContract) external onlyOwner {
        require(dAppContract != address(0), "RewardManager: Invalid dApp contract");
        require(tokenContract != address(0), "RewardManager: Invalid token contract");
        
        dAppTokens[dAppContract] = DAppToken(tokenContract);
        emit DAppTokenUpdated(dAppContract, tokenContract);
    }
    
    /**
     * @dev Update ProofOfUtility contract (only owner)
     * @param _proofOfUtility New ProofOfUtility contract address
     */
    function setProofOfUtility(address _proofOfUtility) external onlyOwner {
        require(_proofOfUtility != address(0), "RewardManager: Invalid ProofOfUtility");
        proofOfUtility = ProofOfUtility(_proofOfUtility);
    }
}

